// Short descriptions of the nodes (the "?" of every node, the tooltips of the Nodes panel and the Help panel).
import type { NodeType } from './types.ts';

export const NODE_HELP: Record<NodeType, string> = {
  import: 'Reads a table: a text file (CSV, TSV, instrument exports), a spreadsheet workbook (.xlsx, .xls, .ods), several files at once, or every data file of a folder (Open a folder, in the order of their names: ready for a Batch). With several files, every sheet or file is a sheet of one workbook (tabs under the worksheet choose the one shown and given on “dataset”; drag a tab onto another to move its sheet; the “workbook” output gives them all, in that order, to Extract column or Sheets to columns). Text files: delimiter (automatic, chosen, or other…: your own, one or more characters: ::, #, \\t for a tab) and decimal separator (automatic or chosen: 1,25 with a decimal comma works), lines to skip at the top, then which line gives the column names (a units line is written into them: Wavelength + nm → “Wavelength (nm)”; a comments line is left out). A column has one header, its name, with its unit in it. The file is kept in the project. Worksheet: the table as a spreadsheet; click a cell, drag or Shift-click for a block, the column letter or the row number for a whole column or row; double-click, Enter or type to change a cell; Ctrl+C / Ctrl+V copy and paste (cells of any spreadsheet; Ctrl+Shift+C with the names); Delete empties the selection, and leaves out the whole columns or rows chosen (Ctrl + click on letters or numbers picks several, not side by side; a button under the table says how many); the small square at the corner of the selection dragged down, up, right or left fills on from its cells (numbers go on as a series: 1, 3 → 5, 7, uneven ones along their straight line; one number is copied, Ctrl held: counted on; Run 1 → Run 2, S01 → S02; other texts repeated), a double-click on it fills down as far as the column beside has values; the corner of the table dragged: the node’s width and the table’s height; the border right of a column letter: that column’s width (a double-click: it fits its values); the border under a row number: the height of all the rows; right-click a column letter, a row number or a cell to insert a column (left / right) or a row (above / below), delete them or move a column (also: drag the letter; Ctrl+Shift+= inserts, Ctrl+− deletes the whole columns or rows selected); right-click a column letter ▸ Lock column: its name and values can no longer be changed by hand and it cannot be deleted (moved and designated: yes), marked by a lock by its letter and tinted cells, until Unlock column (the columns of a Workbook’s inputs, read-only, are tinted the same); every column has its designation (X, Y, Z, ±X, ±Y, Label, Group: what the column is in a plot) used by “Plot these columns” and Plot ▸ Curves from the columns. Plot… (on Import and Workbook, or right-click ▸ Plot these columns): the curves, each its sheet (a workbook), X, Y, ±Y and ±X: any pairs of columns, from any sheet (Sheet1: A–B, Sheet2: D–F, Sheet1 again: C–D …); + Curve, + Curves from the designations of a sheet; the graph: a 1D plot (lines and symbols, lines, symbols, steps, smooth lines, areas, stacked areas, lollipops) or a Bar chart, Histogram, Box & violin, Pie, Polar or Waterfall of the columns of one sheet, a named style; into a new Plot (one, one per sheet or one per curve, together in a Merge if asked) or added to a Plot already there. The changes are kept apart from the file. Export (in the options): the sheet shown or all of them; a text file (the delimiter as in Import: comma, semicolon, tab, spaces, bar or other characters of your own; its extension .csv, .txt, .tsv, .dat or automatic) or an Excel book (.xlsx, a sheet each; several text files in a .zip); the decimal point or comma, the header (the names, none; a line of the designations), missing numbers (empty, NaN, --), masked values (written, left empty, their rows left out), significant digits (0: all), Windows or Unix line ends, a byte-order mark for Excel; Copy as text. Output: the dataset.',
  book: 'A table of your own: type into the cells, paste cells from a spreadsheet or the lines of a text file (Ctrl+V on a cell; commas, semicolons, spaces or tabs between the values), or “Paste as a new sheet” (its first line gives the names when it holds text). Sheets: + adds one, double-click a tab to rename it, ✕ removes it. The same worksheet as Import: select cells, columns or rows, change them, name the columns (with their unit: “Time (s)”), designate them (X, Y, ±Y …), add rows and columns. Inputs A, B, C … (a new one appears when one is used): columns and datasets (e.g. the parameters of a Fit, the points of Pick points) go on the first sheet (Sheet1), or on the sheet named next to their input in the options: an empty sheet shows them (marked ⇢), a sheet with a table of its own gets them at the right of it, and a name not used yet makes a new sheet after the book’s own; inputs on the same sheet go side by side (the shorter columns end in empty cells). Their columns follow the inputs and are read-only (select and copy) but for the designations, which can be changed there (kept by the column’s name); they can be hidden (✕ or right-click; “Show … hidden” at the foot of the table brings them back) and moved, and columns of your own added among them (+ Column, or right-click ▸ Insert column), to type into; the sheets of a workbook connected come as they are, after the book’s own. A matrix connected (Matrix computation after a transpose, say) becomes a table: the node asks whether the rows’ names (or their Y) make the first column and whether the columns’ names (or their X) name the columns; the answer can be changed in the options, next to the input. A sheet of the inputs stays read-only, but its rows can be left out (select them, Delete; Show N hidden rows brings them back) and moved (right-click: Move row up / down). Drag a tab onto another to move its sheet (its own or an input’s): the workbook output gives them in that order; the nodes after it still find each sheet. “Copy into its own sheets” makes copies that can be changed (the connections are removed). Outputs: the dataset of the sheet shown and the workbook (all the sheets). Plot… (on Import and Workbook, or right-click ▸ Plot these columns): the curves, each its sheet (a workbook), X, Y, ±Y and ±X: any pairs of columns, from any sheet (Sheet1: A–B, Sheet2: D–F, Sheet1 again: C–D …); + Curve, + Curves from the designations of a sheet; the graph: a 1D plot (lines and symbols, lines, symbols, steps, smooth lines, areas, stacked areas, lollipops) or a Bar chart, Histogram, Box & violin, Pie, Polar or Waterfall of the columns of one sheet, a named style; into a new Plot (one, one per sheet or one per curve, together in a Merge if asked) or added to a Plot already there. Export (in the options): the sheet shown or all of them; a text file (the delimiter as in Import: comma, semicolon, tab, spaces, bar or other characters of your own; its extension .csv, .txt, .tsv, .dat or automatic) or an Excel book (.xlsx, a sheet each; several text files in a .zip); the decimal point or comma, the header (the names, none; a line of the designations), missing numbers (empty, NaN, --), masked values (written, left empty, their rows left out), significant digits (0: all), Windows or Unix line ends, a byte-order mark for Excel; Copy as text. Set column values (right-click the letter of a column of its own table, as in Origin): the column given by a formula of the sheet’s columns (their letters A, B … or [their names], the inputs’ columns too; ƒ Functions lists every function with an example; Value from a row… takes one value of another row: at(A, 3), first(A, between(B, 10, 20) or B == 7), mean(A, isin(C, 2, 5))), on all the rows or on those chosen (ranges, a list, where conditions are true), the other rows kept or emptied. Auto: ƒ by the column’s letter, its cells tinted and not typed in, computed again whenever the columns it uses change (moved or renamed: the formula follows them); Once: its values written in the cells, as typed. Insert column with formula: a new column, its formula window open. Edit formula; Remove formula: its values kept as typed. A formula that needs itself (through other columns) is said and left empty. rand(), randn(), randint(): the same values every time, New random values for others.',
  extract: 'Takes one column out of a dataset, by its name (the list shows the columns and their rows); from a workbook (Import with several sheets or files), first the sheet: also when the sheet shown of an Import or a Workbook is connected (another sheet chosen connects its workbook output instead). Rows: the rows taken: all, ranges (of the row numbers or of the X values), a list (3, 7-12, 50-end), or where conditions are true (chosen, or a formula: x == 0.5, A > 0 and x < 2, abs(y - ymean) > 3*ysd), of them the odd or even ones; how many are chosen is shown under them. Output: the rows chosen as a column, with its name and unit; or one value of them (Output ▸ one value): the first, the last, the mean, median, sum, min, max, count or SD (the masked rows and the empty cells left out), e.g. the current where the potential is 0.5 V, or a parameter of a Fit with one run.',
  autoextract: 'Columns taken out of every sheet of a workbook (a spreadsheet file, or several files opened together) by rules, one per row: which sheets, which columns, and what they are (their designations: X, Y, ±Y …). Sheets and columns are written the same way: 1, 3-5, 2-end by number; B, D-F by letter (columns); by name (Absorbance); run*, *abs* by a pattern; * all; !3, !Notes left out. In each sheet the columns keep their order, so every Y goes with the X on its left and a ±Y with its Y. The names: “sheet: column”, the column’s, or the sheet’s (a Y named by its sheet: the legend then shows the sheets). Output: one dataset, its columns designated, for Plot (Curves from the columns ▸ From the designations) or right-click ▸ Plot these columns. The reverse: Columns to sheets.',
  tosheets: 'A table made a workbook (the reverse of Sheets to columns), for a Batch over the files, Extract column, a Plot of a workbook. A sheet per column: the columns chosen (2-6, B-F, names, R*; empty: every Y), each with its X (one for all: the designated X or one chosen; the X on the left of each, as X, Y, X, Y pairs; or the row number) and its ±Y, the sheet named by the column. A sheet per value of a column: the rows of every value of the column chosen (S1, S2 …; numbers too), each sheet all the columns, named by the value, in the order the values first come. A workbook coming in: its sheet chosen. Out: the workbook (at most 500 sheets).',
  renamesheets: 'The sheets of a workbook arranged, as Columns arranges columns (once Rename sheets): a row for every sheet in the list: ⠿ dragged to move it (the order then as moved), ticked kept or unticked left out, its new name typed (empty: as the rules below make it). Sheets added: + Sheet… a copy of a sheet (of the workbook or a port, kept or not; changed after it on its own) or an empty sheet (its columns named, separated by commas, and its rows: for the nodes after it to fill); × removes it. The ports A, B … (optional): a table from elsewhere becomes a sheet of its own (a workbook: all its sheets), after the others unless moved. Every name at once: a find and its replacement (text, or a regular expression with its groups $1, $2 … in the replacement: “C-V 20-400K: ” replaced by nothing), or written from what the names say: a pattern as in a Batch (“…Append{n}”: {Name} a number, {Name:text} a word; Guess finds it from the names) and a template ({n} K, {name}: the old name); a name typed in the list wins. Order: as they come (or as moved), by name (run 2 before run 10) or by the first value read. Names met twice numbered. The settings are kept by the sheets’ names: a sheet renamed before this node keeps them. Output: the workbook, for the nodes after it (Sheets to columns, the legends of a Plot, a Batch over the sheets).',
  datamanip: 'Points of a dataset changed on its graph (two columns: X and Y, from the designations or chosen): select them: click a point, drag a rectangle, Shift + drag a lasso, Ctrl adds to the selection; or Pick, one point at a time as the reader finds them (the point nearest the mouse: a click picks it and selects only it, Ctrl + click adds it to the selection, Alt + click takes it out; ← → the next point along X, + and − add it or take it out, Space either; under the graph its row, its exact X and Y changed by Set, an operation of the list, and the points selected listed, × takes one out, a click picks it); or a condition such as y > 1.2 or abs(y - ymean) > 3*ysd, then Mask (kept, but grey or hidden in Plot and left out of statistics, fits and smoothing), Unmask, Delete (the rows leave the output), or Move: drag them (Shift: only Y, Alt: only X) or give ΔX / ΔY, a factor or a value. Every change is an operation in the list below, undone with its ✕; nothing changes in the Import unless you press “Apply to the Import” (deleted and moved points written into its worksheet; masks stay here). A masked row stays masked through Math column, Extract column and the others. Output: the dataset changed. ✚ Add: points drawn by hand (click where a point goes, drag it, double-click to remove it): their rows placed in the order of X (the other columns read between the rows around them), at the end or at the start. The graph: Zoom, Pan, Out, Rescale (X, Y), the data reader (Reader: snap to the data of a curve, the nearest or the one chosen, or free: any place; a click keeps the reading, the arrows move it, Esc lets go) and Large.',
  fit: 'Fits a model to data: a dataset (X, the Y columns and their ±Y from the designations, or chosen) or the data of a Plot curve. Every Y column is a run: a sweep saved in one table is cut into columns first (Split into columns), and every column then knows its swept value. Models: a library (linear, polynomial, exponentials, power, log, Gaussian, Lorentzian, pseudo-Voigt: PsdVoigt1 (one width) and PsdVoigt2 (a Gaussian and a Lorentzian width), A the area, and one with A the height, all with μ, the Lorentzian part of the area: % Gaussian = 100(1 − μ) and % Lorentzian with their errors in the results, Fano, Boltzmann, Hill, logistic, damped sine, coupled oscillators (the spectrum) and the anticrossing of two branches), a formula of your own (every name but x is a parameter; k is the number of the run), or N peaks of one shape over a baseline (numbered from left to right). Parameters: start (empty: guessed from the data), fixed, limits, shared. Fit ranges on X (“Add a range”, then drag on the graph; the same for all runs or each its own), masked points left out, weights 1/σ² from ±Y, √|y| or none; Levenberg–Marquardt. The runs fitted one by one, or together with the parameters marked “shared” common to all (global fit). Results: values ± standard errors, χ², reduced χ², R², adjusted R², RMSE. Outputs: the fit curves; all in one dataset, an X and a fit column for every run (Y column), over the points fitted (several ranges of one run: one fit of their points together, one curve from the first to the last point; or, with “a fit per range”, every range fitted on its own: its parameters, curve and band, a row per range in the parameters), and its 95 % confidence or prediction band as ±Y, drawn shaded; to a Plot\'s dataset port together with the data; the residuals: a dataset, an X and a residual column for every run; a table of the parameters: a row per fit: its number (fit), the data it was fitted on (the value of its block, named as the blocks are: cavity d (nm), cycle, segment, else the Y column), its range and the X fitted from / to, every parameter with its error, N, R², adjusted R², χ², reduced χ², RMSE (any column against any other in a Plot; cut by Split into columns ▸ by a column). The graph: the data, the fit, its band and, in a panel below, the residuals (data − fit; the Residuals button shows or hides it). Linear, errors on X and Y (York): a straight line with the errors of both (a ±Y and a ±X column, designated or chosen; York 2004: Deming regression when the errors are constant), each run on its own. Compare: a second model fitted on the same runs (its parameters guessed; dashed on the graph): χ², R², AIC = N·ln(χ²/N) + 2K, AICc, BIC = N·ln(χ²/N) + K·ln N (K = the free parameters + 1), the Akaike weights, and the F-test when one model is a special case of the other (nested: a line and a parabola); several runs: the same parameters for all? one fit of all the runs with every parameter shared against a fit of each, the F-test of the extra sum of squares (p < 0.05: they differ). The comparison port: a row per fit compared. Peaks: Gaussian, Lorentzian, pseudo-Voigt, Voigt (the exact convolution, from the Faddeeva function: a Gaussian width wG and a Lorentzian width wL), Fano, Doniach–Šunjić (a photoelectron line of a metal, its tail toward higher X). Constraints: lines “name = formula of the other parameters”; w2 = w1, xc2 = xc1 + 1.15, A2 = 0.5*A1: those parameters are given by the others, not fitted, their errors carried from them. Use the fit: Y at X (with the 95 % confidence and prediction intervals), X from Y (a calibration read backwards: the X and its 95 % interval, the mean of × replicates), the limits of detection and quantification (3.3·s / slope, 10·s / slope), and values derived from the parameters (area = A*w*1.0645) with their errors from the covariance: all on the “use of the fit” port. The options in four tabs: Model (the data and the model), Parameters (starts, limits, constraints, the results, χ², AIC, AICc, BIC), Use the fit, Compare. More models: peaks of a given area, Pearson VII, log-normal, a broadened step (erf), a hyperbola, three exponentials, a rise to a limit, the stretched exponential (KWW), Avrami, Gompertz, the 5-parameter logistic, Michaelis–Menten, the Langmuir and Freundlich isotherms, Arrhenius, Vogel–Fulcher–Tammann, Curie–Weiss, Planck’s black body, a sine. Equations: a model given by differential equations; dA/dt = -k1*A; dB/dt = k1*A - k2*B; A(0) = A0; B(0) = 0; y = B: solved numerically (kinetics, populations, any rate law). Errors of X too: the ±X column counted for any model (effective variance; a straight line: York’s fit). Reconvolution: the model convolved with the instrument’s response (IRF: a column, or the “irf” port), its shift and a background fitted (fluorescence lifetimes, pump–probe). A surface: z = f(x, y): a plane, a quadratic surface, a rotated 2-D Gaussian or a formula of x and y; the graph shows the fitted Z against the measured one. Complex: a formula in complex numbers of x (j the imaginary unit), fitted at once to two Y columns: its real part and its imaginary part (an impedance against ω: R0 + R1/(1 + j*x*R1*C1); an equivalent circuit with functions of your own: par(a, b) = a*b/(a + b); R0 + par(R1, 1/(j*x*C1))). Functions of your own work in every formula (f(t) = …; then the formula). For a Nyquist plot (−Im Z against Re Z) set Axes ▸ Aspect = 1: a unit as long on both axes. Fit ▸ a regression: Y on several predictors; linear (the coefficients ± SE, t, p, CI and the variance inflation of every predictor; R², adjusted R², F, AIC, BIC) or logistic for a yes / no response (two levels: 0 / 1 or two texts; the coefficients with z, p and their odds ratios, McFadden’s R², the likelihood-ratio test, the % classified right); the graph shows the observed against the fitted values. The graph: Zoom, Pan, Out, Rescale (X, Y), the data reader (Reader: snap to the data of a curve, the nearest or the one chosen, or free: any place; a click keeps the reading, the arrows move it, Esc lets go) and Large.',
  calculus: 'The derivative or the integral of data, on unevenly spaced X too. Input: a dataset (X and the Y columns from the designations, or chosen: each Y with its X gets its own result) or the data of a Plot curve. Differentiate: order 1 or 2; central (the mean of the slopes to the two neighbours) or Savitzky–Golay (a polynomial over a window of points: smooths noisy data). Integrate: trapezoid rule, cumulative; mathematical (signed) or absolute area; over a baseline found in every range: y = 0, a constant, a straight line between the ends of the range (each end the mean of “End points”), the lowest point, the rubber band, points placed on the graph (straight or spline), another curve (a column with its own X, or the curve on the “baseline” port: the area between two curves), or one found from the data, the peaks left above it; the iterative polynomial, asymmetric least squares (smoothness 10^λ, asymmetry p), airPLS, SNIP (its window, on the log-log-square-root scale or not): or, for photoelectron spectra, Shirley and Tougaard (the losses toward a higher or a lower X, C); “Under: the dips” puts the one-sided ones over the dips (the same list as Peak analyzer and Peak width): (e.g. a scan going up and coming back, cut by Split into columns ▸ where X changes direction). Ranges: “Add a range”, then drag on the graph (none: all X), the same for every Y or their own for each; for an integral separate (from 0 in each) or combined (on across the gaps); hatched on the graph. Outputs: a dataset with X and every Y followed by its result (empty outside the ranges); for an integral also the areas (a row per range, in the column “region”), the baseline (X and its values for every Y, as drawn) and the total area of the first Y. The graph: Zoom, Pan, Out, Rescale (X, Y), the data reader (Reader: snap to the data of a curve, the nearest or the one chosen, or free: any place; a click keeps the reading, the arrows move it, Esc lets go) and Large.',
  peaks: 'Finds, measures and separates the peaks of every Y column (with its X), in four steps: 1 Data, 2 Baseline, 3 Peaks, 4 Fit. The peaks found automatically (the most prominent ones, all of one shape) or chosen by hand: + Region, then drag across a peak on the graph: the peak is taken at the maximum (or the minimum: a dip) of the data over the baseline in that region and its centre stays in it in the fit, the region drawn as a band in the peak’s colour (its edges dragged to change it, or typed); + Point, then a click: a peak at that place; each its own shape; the numbers of the peaks over the frame, a diamond on every peak. The fit is made when you press Run analysis (a setting changed since: “settings changed: Run again”; until then the peaks are measured on the data). Between From and To (empty: all X). Baseline: fitted together with the peaks (constant, linear, quadratic), or fixed under them: y = 0, a constant, a straight line between the ends, the lowest point, the rubber band (the lower hull of the data), points placed on the graph (Baseline points: click to add, drag to move, double-click to remove; joined straight or by a spline), another column (with its X), or one found from the data, the peaks left above it: the iterative polynomial, asymmetric least squares (smoothness 10^λ, asymmetry p), airPLS, SNIP (its window, on the log-log-square-root scale or not): or, for photoelectron spectra, Shirley and Tougaard (the losses toward a higher or a lower X, C); “Under: the dips” puts the one-sided ones over the dips; “subtract” takes it away from the outputs. Peaks: found in every run (maxima, or dips, or both; the most prominent, at least a % of the largest; shoulders (a peak hidden in the side of another) from the second derivative), or a list of your own: “Found → list” keeps the ones found, “+ Peak” then a click on the graph adds one where you see it (a shoulder), each with its shape (Gaussian, Lorentzian, pseudo-Voigt, Fano). Fit the peaks: all fitted together as a sum (peak deconvolution: overlapping peaks separated), each in its colour on the graph with its number, the envelope (their sum) in black, the residuals (data − fit) in a panel below: the Residuals button shows or hides it; else measured on the data (between its baseline and the valleys). Outputs: the data: X, Y (or Y − baseline), the baseline, every peak and the envelope (a run after another), the table of the peaks (a row per peak: center, height, FWHM, area, area %, a pseudo-Voigt’s % Gaussian and % Lorentzian (from μ, the Lorentzian part of the area), and the errors and R² of the fit, or the centroid and limits), the baseline, the residuals. Shapes: Gaussian, Lorentzian, pseudo-Voigt, Voigt (exact: its Gaussian width w and Lorentzian width wL), Fano, Doniach–Šunjić. 2× on a peak of the list makes it a doublet (spin–orbit: 2p, 3d, 4f): a second peak of the same shape and width at ΔX, its area a fixed ratio of the first (0.5, 0.667, 0.75): linked to it in the fit; the table marks it “(1)”, the peaks output with “doublet of”. The graph: Zoom, Pan, Out, Rescale (X, Y), the data reader (Reader: snap to the data of a curve, the nearest or the one chosen, or free: any place; a click keeps the reading, the arrows move it, Esc lets go) and Large.',
  normality: 'Is every group normal? Shapiro–Wilk (the most powerful for small samples), Anderson–Darling, Kolmogorov–Smirnov with the mean and SD estimated (Lilliefors), D\'Agostino–Pearson K²; and an outlier test: Grubbs (the value farthest from the mean) or Dixon\'s Q (3 to 10 values). The data: each group a column (columns), or a value column and a factor column (indexed). Outputs: the tests (a row per group and test: statistic, p, significant at α), the outliers, the groups (N, mean, SE, SD, CI, median, min, max: mean ± SE ready for a Plot).',
  ttest: 't-tests: one sample against a value μ; two independent samples: Welch (unequal variances, the default) or Student (equal variances): with the F test and the Brown–Forsythe (Levene) test of the variances; paired (the same subjects twice: a row per subject, two columns). Two-sided or one-sided. The data: two columns, or a value column and a factor with two levels (indexed); paired: a row per subject. Outputs: the test (t, df, p, the difference with its CI, Cohen\'s d) and the groups; the report says it in words. Power and sample size: the power of the test at the effect found (Cohen’s d) (the chance of finding an effect of that size), and the size needed for a target power (0.8 unless set), from the noncentral t.',
  anova: 'Analysis of variance. One-way (each group a column, or indexed): F, p, η², ω²; Welch\'s ANOVA when the variances differ; post-hoc comparisons of every pair: Tukey HSD (Tukey–Kramer for unequal groups), Bonferroni, Holm, Scheffé, Fisher LSD, Games–Howell (unequal variances): or Dunnett: every group against a control (chosen; its p and simultaneous intervals from the multivariate t, also after repeated measures). Two-way with repeated measures (indexed: the value, factor A, factor B and the column of the subjects): B within the subjects and A between them (groups of subjects; unequal groups by Type III sums), or both within: each effect against its own error, Mauchly’s test, the Greenhouse–Geisser and Huynh–Feldt corrections. Mixed-effects model (as Prism fits for repeated measures with values missing): a random intercept per subject by REML, factor A (and B with the interaction) tested by Type III F tests with Satterthwaite’s degrees of freedom, the variances and the intraclass correlation; every value used. Two-way with interaction (indexed: a value column and two factor columns; Type III sums of squares, unbalanced designs too), partial η². Repeated measures (a row per subject, a column per condition): Mauchly\'s test of sphericity, Greenhouse–Geisser and Huynh–Feldt corrections, paired comparisons (Holm or Bonferroni). Checks: Brown–Forsythe (equal variances), Shapiro–Wilk of the residuals. Outputs: the ANOVA table, the post-hoc table, the groups (mean ± SE for a Plot), the checks. Power and sample size (one-way): the power at the effect found (Cohen’s f, from η²) and the size per group needed for a target power, from the noncentral F.',
  nonparam: 'Tests without the normal assumption (ranks). Mann–Whitney U (two independent groups; exact for small samples without ties), Wilcoxon signed-rank (paired: a row per subject, two columns; or one sample against a median μ), sign test, Kruskal–Wallis (2 groups or more) with Dunn\'s comparisons (Holm or Bonferroni), Friedman (repeated: a row per subject, a column per condition). Outputs: the test, the groups (N, median, quartiles, mean rank), the post-hoc table.',
  correl: 'Correlations between every pair of the columns chosen (empty: every numeric column but those designated –): Pearson r (with its confidence interval), Spearman ρ (ranks), Kendall τ-b (ties corrected); the rows where both are numbers. Outputs: the pairs (r, p, N, CI, significant at α) and the matrix of r. Matrix order: as given, or clustered (related columns next to each other, by 1 − |r|): for a correlation map. Principal components (PCA), of the correlations or of the covariances: the eigenvalues and the % of the variance each component explains, the loadings of the columns, the scores of every complete row (PC1 against PC2: a scores plot).',
  padjust: 'Many tests at once (genes, wavelengths, every pair of groups) give false positives by chance; this node adjusts their p-values. In: any table with a column of p-values (the output of a test node, a list typed in a Workbook); auto: the column named p, else the first with p in its name. Methods: Holm (step-down, the default: never worse than Bonferroni), Bonferroni (p × the number of tests), Hochberg (step-up, independent tests), Hommel; these keep the chance of any false positive under α (the family-wise error). Benjamini–Hochberg and Benjamini–Yekutieli (any dependence) keep the share of false positives among the results called significant under α (the false discovery rate: for many tests, more power). The values that are not numbers are kept and not counted, as R\'s p.adjust. Out: the table as it came, with the adjusted p and Significant (at α) beside every p.',
  contingency: 'Counts of categories: are two categories related (independence), did paired answers change (McNemar), do counts follow expected proportions (goodness of fit)? Layout: a row per observation (the category of its row and of its column, e.g. Treatment and Outcome), a table of counts (a column of row names, a column of counts for every column of the table), or counts with their two categories. Independence: Pearson\'s χ² (with Yates\'s continuity correction for a 2 × 2 table, if ticked), the G-test (likelihood ratio) and Fisher\'s exact test (2 × 2 and larger tables: every table with the same totals enumerated, or 100 000 drawn at random when they are too many); with expected counts under 5 the report takes Fisher\'s. Measures: Cramér\'s V; for a 2 × 2 table φ, the odds ratio (Woolf\'s interval; a zero cell: 0.5 added to every cell), the relative risk (Katz\'s interval) and the risk difference, all of the first column (the event) in the first row against the second. McNemar: a paired 2 × 2 table (the same subjects before × after), χ² and the exact binomial p. Goodness of fit: one category, its counts against equal proportions or a column of expected proportions (or counts); χ² and G. Outputs: the tests, the measures, the cells (observed, expected, the % of the row, of the column and of the total, the adjusted residual: over ±2 the cells that make the difference, the part of χ²) and the table with its totals.',
  roc: 'How well a score (a test\'s value, a biomarker, a model\'s probability) tells two classes apart. In: a row per case, its true class (two values: the positive one chosen, else 1, yes, positive, case … else the second) and one score column or more. Direction: a higher score means positive, a lower one, or auto (from the medians of the two classes). Every score: the ROC curve (1 − specificity on X, sensitivity on Y, a point for every threshold: positive when the score is at it or beyond), the AUC with DeLong\'s standard error, its interval and the p against 0.5 (chance); the table of every threshold (sensitivity, specificity, PPV, NPV, accuracy, Youden\'s J, the likelihood ratios LR+ and LR−) and the best threshold with its confusion matrix (TP, FP, FN, TN), by Youden\'s J, the point nearest the top-left corner, or the best specificity at a sensitivity reached (or the reverse). Two scores or more of the same cases: DeLong\'s test of every two AUCs (only the rows with every score). The curves go to a Plot (a diagonal from (0, 0) to (1, 1) as a reference line).',
  survival: 'Time to an event (death, failure, relapse) when some subjects leave before it (censored). In: a row per subject: the time, the event column (1: it happened, 0: censored; or the value chosen in Event is), the group (optional). Kaplan–Meier: the survival S(t) at every time, its interval from Greenwood\'s variance on the log–log scale (or log, or plain), the median survival with its interval (where the band crosses 0.5; not reached: blank). Groups compared by the log-rank test (Mantel–Cox: every time alike), Gehan–Breslow–Wilcoxon (the early times weigh more) or Tarone–Ware; three groups or more: every two groups too, their p adjusted by Holm. Two groups: the hazard ratio of the second to the first (Mantel–Haenszel) with its interval. Times: those of S(t) in the summary and of the numbers at risk (auto: about six round ones). Outputs: the test, the curves (Time X, Survival Y, Lower, Upper of every group, from (0, 1): to a Plot in the step mode, the bounds dashed), the censored times on their curves (to a Plot as + symbols), the summary (N, events, censored, the median and its CI, S at the times), the numbers at risk, the hazard ratio. Cox regression: in a Python script (statsmodels).',
  regress: 'The linear model: Y explained by several predictors at once, each with its own effect, the others held constant. Predictors: numbers, or categories (text columns, or those ticked as categories: their levels compared with a reference, chosen or the first in order: I before II, 2 before 10); Interactions: the product of every two predictors (a category and a number: different slopes per group, ANCOVA); no intercept: the line through 0; Weights: a column of σ (weighted least squares, 1/σ²). Least squares by QR; the rows with a value missing are left out; a predictor that repeats the others is left out with a warning. Outputs: the coefficients (estimate, SE, t, p, CI, the standardized β, the VIF: over 10 a predictor nearly repeated by the others), the ANOVA (Type II: every predictor after the others, F and p), the model (R², adjusted R², RMSE, F and its p, AIC, BIC, Durbin–Watson for residuals in order, Breusch–Pagan for a spread that changes, Shapiro–Wilk of the residuals) and the fitted values (Predicted as X and Residual as Y: a residual plot; the studentized residual, the leverage, Cook\'s distance and the influential points, over 4/N). A curve of one X (exponential, peaks …): Fit.',
  power: 'Plans an experiment: how many subjects a test needs, its power, or the smallest effect it can find (a calculator: no data in). Tests: t-tests (two samples, paired, one sample: Cohen\'s d), the one-way ANOVA (Cohen\'s f, the groups), two proportions (p1 and p2: Cohen\'s h, as statsmodels), a correlation (r, by Fisher\'s z), χ² (Cohen\'s w and the df: categories − 1, or (rows − 1)(columns − 1)), the log-rank test (the hazard ratio, the share of the subjects that reach the event: Schoenfeld\'s formula, the events needed). Find: the size from the effect and the power; the power from the effect and the size; the smallest effect found with the power at the size. Sizes per group for the two-sample tests (n2 = ratio × n1), in all for the others. α, two-sided or one-sided. Outputs: the result (the value found marked) and the power curve (the power against the size: to a Plot, the gain of every subject more). Effect sizes of Cohen: d 0.2, 0.5, 0.8; f 0.1, 0.25, 0.4; r and w 0.1, 0.3, 0.5 (small, medium, large).',
  resample: 'Intervals and tests without assuming a distribution, by resampling the data. Bootstrap: B resamples with replacement (of the sample; of each of two samples; of the pairs for a correlation), the statistic of each; the estimate, its bias and SE, its interval: BCa (corrected for the bias and the skewness, from the jackknife: the default, as SciPy), percentile or basic. Statistics: mean, median, SD, CV, a percentile; the difference of two means or medians, the ratio of two means; Pearson r and Spearman ρ of pairs. Permutation test: the labels of two samples shuffled (or one side of the pairs: a correlation), every arrangement when they are at most the resamples (exact), else that many at random (p = (count + 1)/(B + 1)); two-sided p twice the smaller tail. The samples: columns, or a value column with a factor of two groups. A seed: the same seed, the same result. Outputs: the result and the resampled values (to a Histogram).',
  distfit: 'Which distribution do the values follow? Every distribution ticked fitted by maximum likelihood: Normal, Lognormal, Exponential, Weibull, Gamma (these four with their location at 0: values over 0), Logistic, Gumbel, Uniform, Beta (values between 0 and 1); with life data (a status column: failed or suspended) the suspensions in the likelihood. Ranked by AIC, with ΔAIC, the Akaike weights (the chance each is the best of those tried) and BIC; the Kolmogorov–Smirnov D with its exact p and the Anderson–Darling A² (without suspensions; the parameters fitted to the same data make the p too large: a guide). Outputs: the ranking, the parameters with their intervals (from the Fisher information), the curves (the PDF and the CDF of every distribution over the values: to a Plot, over a histogram of the data). The probability plot of one: Probability plot.',
  agree: 'Do raters (instruments, observers, repeated measurements) agree, and is a scale reliable? A row per subject, a column per rater or item. κ, for categories: two raters Cohen\'s κ (unweighted, or with linear or quadratic weights for ordered categories: a near miss counts in part), its SE and interval, the test of κ = 0, the observed and chance agreement and the table of the ratings; three raters or more Fleiss\'s κ; the words of Landis and Koch. ICC, for numbers: all six forms (Shrout and Fleiss; McGraw and Wong): ICC(1,1) one-way, ICC(A,1) two-way absolute agreement, ICC(C,1) two-way consistency, and the same for the mean of the raters (k), with F, p and intervals (as pingouin); the words of Koo and Li. Cronbach\'s α of the items of a scale, its interval (Feldt), every item\'s correlation with the rest and α without it. Lin\'s concordance ρc of two measurements: precision (Pearson r) and accuracy (Cb), its interval from Fisher\'s z. Two methods with a bias and limits: Bland–Altman; their regression: Method comparison.',
  methcomp: 'Two methods (instruments, labs, assays) measuring the same samples: is one the other plus a constant (an intercept) or times a factor (a slope)? Passing–Bablok (1983): no assumption on the errors, robust to outliers; the slope the shifted median of the slopes between every two points, its interval from the ranks, the intercept and its interval, the CUSUM test of linearity (a small p: the relation is not linear, the method does not apply). Deming: the errors of both methods normal, λ the ratio of their variances (Y to X; 1: as precise), the slope and intercept with jackknife SE and t intervals. The methods agree when the slope\'s interval holds 1 and the intercept\'s holds 0. Outputs: the regression, the lines with y = x over the range of X (to a Plot with the data) and the residuals. The differences against the means: Bland–Altman.',
  logistic: 'The probability of an outcome of two values (yes / no, died / alive, 1 / 0) explained by predictors: the binary logistic regression, by maximum likelihood (Newton\'s method). Predictors as in Linear regression: numbers or categories (their reference chosen or the first in order), every two predictors\' interaction, the intercept. Outputs: the coefficients (estimate, SE, z, p, CI, and the odds ratio with its CI: how many times the odds grow for a unit more, or against the reference), the model (log-likelihoods, the likelihood-ratio test, the pseudo-R² of McFadden, Cox–Snell and Nagelkerke, AIC, BIC, the Hosmer–Lemeshow test of the fit in deciles of the probability), the classification at a threshold (observed against predicted, % correct) and the fitted rows (the probability, the predicted outcome, Pearson and deviance residuals; Observed and Probability to a ROC curve for the AUC). A warning when the outcome is separated by the predictors, or the events are fewer than 10 per predictor.',
  curvemath: 'Two curves A and B, each with its own X: from a dataset or a sheet of a workbook on A and on B (for each: the sheet, X and Y chosen; B: else the second Y of A), or from columns: X (else the row number), Y A and Y B. Operations: as many as you like (+ Add operation), each with its settings and its own output: ΔX at Y and ΔY at X together, for example. The node draws the curves and, over them in the colour of every operation, what it computes: the levels with the two crossings and the ΔX between them, the X with the two values and the ΔY, the intersections, the curve computed, the levels of a step; the values of ΔX at Y / ΔY at X listed in the options of each operation: typed, removed (✕), added (Add a value, + Range: start:step:end) or picked on the graph (Pick on the graph, or + Y / + X above the plot, then a click; a line dragged moves its value, a double-click removes it); ranges: from, to and the points (or the step) between them, typed or drawn on the graph (Draw a range: drag across it); shown as bands, their edges dragged; the intervals of X of the intersections and of a uniform grid as bands too (Draw it). The curves computed (A × B, A / B …) on the axis of A and B or, when of another size, on their own axis at the right (automatic; or chosen: Curves computed), so every curve stays visible. ΔX at Y: where each curve crosses the Y values (one, a list, or start:step:end: e.g. the width of a loop against Y, the shift of a spectrum at a reflectance), the first, the last or every crossing, ΔX = X of B − X of A (or its absolute value). ΔY at X: the two Y at the X values. Intersections: every point where the curves meet, segment by segment in the order measured (several crossings, loops, curves going back on X, different X): a crossing (B passes above or below A) or a touch (B meets A and stays on its side, or a curve ends on the other); every one, the first or the last along A, only in a range of X, the touches too or not; one row each: #, X, Y, the rows of A and B (between two rows: 12.4), the direction (+1 B above, −1 below, 0) and the kind. Where the curves lie on top of each other is warned of (only where they meet and part is counted). A − B, A + B, A × B, A / B, the mean: on the X of A, of B or a uniform grid, the other curve read there by straight lines (empty outside it). Formula: lines “name = expression” of the curves; xmin(A), ymin(A), xmax, ymax (their place refined by a parabola), xat(A, y), yat(A, x), fwhm(A) / fwhmdip(A) (the width at half height over the line between the ends, on the data), height, depth, area, centroid, mean, count, each with a range of X if wanted (xmin(A, 600, 700)), the results of the lines above usable below: e.g. S = (xmin(B) − xmin(A)) / (1.345 − 1.333), the sensitivity of a plasmon dip. For every Y of A: a row per curve with its block’s value (a sweep cut by Split into columns). Output: a dataset ready for a Plot (Y / X, the two values, the difference designated Y; a formula: its results). Step response: of A (and of B): the start and end levels, the rise (or fall) time between two levels (10–90 %), the delay to 50 %, the peak and its time, the overshoot and undershoot (% of the step), the settling time (within ± 2 %); a pulse (it comes back): its rise, its fall and its width at half height.',
  peakwidth: 'A peak’s or a dip’s width measured on the data (no fit), and the minimum and maximum, in ranges drawn on the graph (as in Integrate and Fit; common or of every run; none: all X), for every Y (with its X; masked points left out). Peak, dip or auto (the larger deviation). The baseline, found in every range: the line between the ends of the range, y = 0, a value, the lowest point, the rubber band, points placed on the graph (● Baseline points), another column, or one found from the data, the peaks left above it: the iterative polynomial, asymmetric least squares (smoothness 10^λ, asymmetry p), airPLS, SNIP (its window, on the log-log-square-root scale or not): or, for photoelectron spectra, Shirley and Tougaard (the losses toward a higher or a lower X, C); “Under: the dips” puts the one-sided ones over the dips (for a dip: over it). FWHM: the two crossings of half the height over the baseline, linear between the points (a side that does not reach it: empty, said). Output: a row per run and range; the run (its block’s value when cut by Split into columns), the range (column “region”), the place and value of the extremum (refined by a parabola), the height or depth, FWHM (designated Y) and its left and right ends, Q = X / FWHM, the X and value of the minimum and of the maximum, the number of points in the range and their % of all the points of the curve. The same measures as the formulas of Curve math (fwhm, xmin …). The graph: Zoom, Pan, Out, Rescale (X, Y), the data reader (Reader: snap to the data of a curve, the nearest or the one chosen, or free: any place; a click keeps the reading, the arrows move it, Esc lets go) and Large.',
  translate: 'Curves resized and moved on X and / or Y, the data kept as they are. Input: a dataset, and / or columns on A, B, C …, their designations (X, Y, ±Y, ±X, –) chosen here, every Y with the X on its left. Resize (first), X and Y each: by a factor about a point that stays (0, the first point, the middle, the peak or a value), a range brought to another (empty ends: the data of each curve), or two values brought to two others (a calibration). Move (then): by values (ΔX, ΔY for all, or each curve its own), a point (the maximum, the minimum, the first or last point, or the value at an X) brought to X₀ and / or Y₀, or in steps (curve k by k·Δ: a waterfall). The graph in the node: the curves as they come out, and as they came in (a thin grey line); Move drags them (Alt: one curve, Shift: one axis), Resize stretches them (drag across: X, up or down: Y; the wheel: X, Shift + wheel: Y); Reset X / Reset Y undo the resize and the move on that axis; Rescale X / Y fit that axis to the new curves; its limits are kept with the node (zoom, pan, or typed in Graph), to move the curves further. The errors are resized with their values. Outputs: the curves, and every curve with its ΔX, ΔY, its factors and offsets.',
  siggen: 'Makes a signal, to teach or to test the other nodes on data whose answer is known; no input, out a table. A sum of components (+ Add component, each on or off, its numbers, a column of its own if asked): waveforms (sine, square with its duty, triangle, sawtooth, a pulse train with its width, rise and fall, a step, an impulse, a damped oscillation, a Gaussian pulse with a carrier, an exponential), a chirp (linear, quadratic, logarithmic or hyperbolic from f₀ to f₁ over its duration, as scipy.signal.chirp; no envelope, a Gaussian one or a Tukey window), peaks (Gaussian, Lorentzian, Voigt exactly by the Faddeeva function, Fano (q + ε)² / (1 + ε²) with ε = 2(x − E₀)/Γ), two coupled oscillators driven through the first (Joe, Satanin and Kim 2006: their absorbed power or amplitudes; g half the splitting at resonance: strong coupling, an anticrossing, Fano-like dips), a polynomial baseline; over X from, to, with so many points. C–V of a structure, against its voltage. MOS capacitor (Sze and Ng, Physics of Semiconductor Devices, ch. 4; the algorithms of razvan_CV_ideal_test.m and CV_ideal.m): the semiconductor’s charge from Poisson’s equation, V_G = V_FB + ψs − (Qs + Qit)/C_ox solved for ψs at every voltage, C_ox in series with C_s; n- or p-type, its doping (cm⁻³); deep depletion (the majority carriers only: no inversion layer), low frequency (the minority carriers and the traps follow: back to C_ox in inversion), high frequency (they do not: C_s held at 2φ_B as Sze, at 2.10|u_B| + 1.33 kT/q as CV_ideal.m, or exact as Lindner and Brews, the majority carriers responding on the equilibrium profile), or low and high frequency both; interface traps constant or U-shaped over the gap (donors below mid-gap, acceptors above): their charge stretches the curve and moves the flat band, their capacitance adds to C_s at low frequency (the high–low and Terman methods read them back); the oxide, the material (permittivity, gap, nᵢ from the effective masses or typed), V_FB typed or from the work functions with a fixed oxide charge. p–n junction (Sze and Ng, ch. 2): abrupt, C = εA/W, W = √(2ε(V_bi − V − 2kT/q)/qN_eff), V_bi = (kT/q)·ln(N_A·N_D/nᵢ²); linearly graded, W = (12ε(V_bi − V)/qa)^⅓ with V_bi = (2kT/q)·ln(aW/2nᵢ) self-consistent; V_bi typed if asked. Schottky diode (Sze and Ng, ch. 3): W = √(2ε(V_bi − V − kT/q)/qN), V_bi = φ_B − (kT/q)·ln(N_c/N), the barrier typed or φm − χ (V: the metal’s voltage). Varactor: the SPICE junction, C_J0·(1 − V/V_J)^−M, a straight line beyond F_C·V_J (M ½ abrupt, ⅓ graded, above ½ hyperabrupt). MIM capacitor: C₀·(1 + α₁V + α₂V²), C₀ = ε₀εA/d. Ferroelectric capacitor (Miller, Nasby, Schwank, Rodgers and Dressendorfer 1990): P = P_s·tanh((E ∓ E_c)/2δ), δ = E_c/ln((1 + P_r/P_s)/(1 − P_r/P_s)), C = A(ε₀ε_b + dP/dE)/d, up and down (its butterfly), P written too. Semiconductor electrode (Mott–Schottky): Poisson’s equation with the Helmholtz layer in series (0: none), its potential E against the reference, the flat band E_fb; in depletion 1/C² = 2(E − E_fb − kT/q)/(qεN·A²). Double layer (Bard and Faulkner, §13.3): Gouy–Chapman, C_d = √(2z²q²εn⁰/kT)·cosh(zqφ_d/2kT), with a Stern layer C_H in series (E − E_pzc = φ_d + σ/C_H); a z:z electrolyte, its concentration, the solvent’s permittivity. For all: a curve for every temperature typed (not for the varactor, MIM and ferroelectric); measured in parallel mode through a series resistance and a leak at a frequency (C_m and G_m); pF, nF, F, nF/cm², µF/cm² or C/C_ox; 1/C², the depletion width W, ψs (or φ_d and σ) as columns if asked. The impedance of a circuit: built as in Equivalent circuit (the same elements and drawing), its values, from a lowest to a highest frequency, so many points a decade; out f, Z′, −Z″, |Z|, the phase. On any of them: noise (white, pink 1/f, brown 1/f²; normal or uniform; by a signal-to-noise ratio in dB or its SD; for an impedance, a part of |Z| on both parts), a drift, spikes, missing points, uneven sampling (components), the clean signal as a column too, a seed (the same seed, the same signal). Its graph in the node: the signal made (with noise: as dots, on the clean one), the C–V curves one a temperature, for an impedance its Nyquist plot and its Bode plots (Graph of).',
  smooth: 'Smooths every Y column. Adjacent averaging (a window of points), Savitzky–Golay (a polynomial of a degree over the window: keeps the height and width of peaks), median (removes spikes), Hampel (only the outliers replaced: a point further than a number of robust SDs, 1.4826 · MAD, from the median of its window takes that median; the others kept, the points replaced marked in the graph), Gaussian (σ in points), LOWESS (a line fitted locally to a fraction of the points with tricube weights, with robustness passes: X need not be even), FFT low pass (a cut-off as a fraction of the Nyquist frequency). The ends: reflected, mirrored, the end value repeated, the window shrunk, or (Savitzky–Golay) the polynomial of the first / last window. The filters count points: X evenly spaced. Output: X, the data (optional), the smoothed curve, the residual (optional); the graph shows them. Wavelet denoising: the discrete wavelet transform (Haar, Daubechies 2 or 4, Symlet 4; a number of levels), the details under the universal threshold σ·√(2 ln n) removed (soft: shrunk, hard: cut; × a factor): keeps the edges and the peaks sharp. Ranges (Add a range, dragged on the graph; the same for every Y, or per Y): each range smoothed on its own (the window sees only its points); outside them the data as they are, or nothing (Outside). The graph: Zoom, Pan, Out, Rescale (X, Y), the data reader (Reader: snap to the data of a curve, the nearest or the one chosen, or free: any place; a click keeps the reading, the arrows move it, Esc lets go) and Large.',
  baseline: 'Takes the baseline (the background) off every Y column: subtracted, or divided by (a transmission, a flat field). Every baseline of Integrate, Peak analyzer and Peak width: a value, the line between the ends (each end the mean of a few points), the lowest point, the rubber band (the lower hull), points placed on the graph (Baseline points: click to place, drag to move, double-click to remove; joined straight or by a spline), another curve (a column of the data, or the curve on the “baseline” port); found from the data, the peaks left above it (or the dips below): the iterative polynomial, asymmetric least squares (smoothness 10^λ, asymmetry p), airPLS, arPLS (Baek, Kim and Lee 2015: its weights from the spread of the points below the curve, sound on noisy data), SNIP (its window, on the log-log-square-root scale or not); for photoelectron spectra Shirley and Tougaard. Ranges (Add a range, then drag on the graph; the same for every Y or each its own): the baseline found in every range on its own, outside them the data left out or as they are; or Polynomial through background ranges: the ranges drawn over the parts with no peak, a polynomial of a degree through their points, under all the data. The graph: the data with the baseline over it (dashed), the corrected curve below; Zoom, Pan, Out, Rescale, the data reader and Large. Outputs: the corrected curves (the data too if asked) and the baseline (to the baseline port of Integrate, or a Plot).',
  waveform: 'Measures a signal in time as an oscilloscope does, in every range drawn on the graph (none: all of it), for every Y. The two levels: the base and the top from the histogram of the values (IEEE 181: the modes below and above the middle, not moved by the overshoot or the noise), the minimum and maximum, or given. The edges: the crossings of the middle with a hysteresis (the signal must go so far past it, in % of the amplitude: no false edges from noise), every one at the place it crossed (between the samples). For every edge its rise or fall time between the reference levels (10–90 % or as set), its overshoot (or undershoot) in % of the amplitude, its settling time (until it stays within the band of its level). For the whole: the period and the frequency, the positive and negative pulse widths, the duty cycle, the mean, RMS and AC RMS, peak to peak, the crest factor, the crossings of the mean. The graph: the data with the levels, the edges marked (green rising, red falling) with their rise and fall spans; Zoom, Pan, Out, Rescale, the data reader and Large. Outputs: the measurements and the table of the edges.',
  steps: 'Finds the places where a signal jumps from one level to another (single-molecule steps, a current through an ion channel, a drift in steps), in every range drawn on the graph or all of it, for every Y. A change of the mean (the noise the same throughout) or of the mean and the noise. PELT (Killick, Fearnhead and Eckley 2012): the exact best segmentation for a penalty, fast; or binary segmentation (the best split, again and again, or so many changes). The penalty, what a change must gain: BIC (the usual), AIC (more changes) or a factor of your own (larger: fewer changes), scaled by the noise found from the differences of neighbours (not raised by the steps); the fewest points of a level. Outputs: the segments (start, end, duration, mean, SD), the steps (where, the step size: to a Histogram for the size of the steps, the dwell time before it) and the step curve with the data (to a Plot). The graph: the data with the step curve over it and the changes marked; Zoom, Pan, Out, Rescale, the data reader and Large.',
  events: 'Averages the parts of a long record around repeated events (evoked responses, pulses, cycles): the noise falls as the square root of their number. The triggers: the signal crossing a level (rising or falling; empty: the middle of its range) with a dead time, the rows of a column of marks (a number other than 0, or a text), or times written; only inside the ranges drawn on the graph, if any. The window before and after every trigger (empty: from the spacing of the triggers); every segment read on a common lag, its level before 0 taken off if asked; a segment whose window leaves the data is not used. Outputs: the average (lag, mean, SD or SE as ±Y, N: to a Plot with an error band), every segment (to a Plot or a Waterfall) and the triggers. The graphs: the record with the triggers marked (grey: not used) and the level; below, the average with its band and the segments in grey; Zoom, Pan, Out, Rescale, the data reader and Large on both.',
  wavelet: 'Wavelets: what happens at which scale, and when. In the first range drawn on the graph (none: all of it), X evenly spaced. Continuous transform (Torrence and Compo 1998, as pycwt): Morlet (ω0 6: sharp in frequency), Paul (order 4: sharp in time) or DOG (order 2, the Mexican hat: real); the scales in voices per octave between two periods; the power at every time and period with the cone of influence (outside it the ends of the record distort the power) and its significance against red noise (the lag-1 autocorrelation of the data) or white noise; the global spectrum (the power averaged in time) with its significance, the power over a band of periods in time (below the data), the ridge (the period of the largest power at every time). Wavelet coherence (Grinsted, Moore and Jevrejeva 2004; Morlet): where in time and at which periods two signals go together even for a while, and their phase (positive: the first ahead). Multiresolution analysis (the maximal overlap transform, MODWT, as PyWavelets\' mra): the signal split into details D1 (the finest) … DJ and a smooth SJ that add up to it; a curve rebuilt from the parts chosen (e.g. D3-D5, S: without the noise of D1, D2), the share of the energy in every part; Daubechies 1–10, Symlets 2–10, Coiflets 1–5. Denoising: the discrete transform, the details thresholded (universal, SURE or BayesShrink; soft or hard; the noise σ from the finest details or of every level). Peaks: the ridges of a Ricker (Mexican hat) transform over widths followed down the scales, as SciPy\'s find_peaks_cwt: peaks on a sloping background or in noise. Outputs: over time (the band\'s power or coherence, the ridge, the cone; the parts; the denoised curve; the peaks), the map (time, period, value, its significance or phase, in the cone: to a Contour), the global spectrum, the energy or the thresholds. The graphs: the data with the ranges and the rebuilt curve or the peaks over it, the result below; the global spectrum on its own axis; Zoom, Pan, Out, Rescale, the data reader and Large.',
  fraccalc: 'Derivatives and integrals of any order α (negative: an integral; −0.5 the semi-integral, 0.5 the semi-derivative, 1 the usual derivative), of every Y, from the start of every range drawn on the graph (the lower terminal). Definitions: Riemann–Liouville (the usual), Caputo (the values at the start left out: initial-value problems, viscoelastic models), both by product integration of the data joined by straight lines (exact for them, X may be uneven); Grünwald–Letnikov (the limit of differences; X even, first order); Weyl in the Fourier domain ((iω)^α; periodic data, the mean left out). Several orders at once: a curve each. Along X (X the time), or along the rows with X a potential swept at a scan rate (a cyclic voltammogram: both sweeps in time order, the time |ΔE| / rate). Electrochemistry, convolution voltammetry (Oldham, Anal. Chem. 44 (1972) 196; Imbeaux and Savéant, J. Electroanal. Chem. 44 (1973) 169; Bard and Faulkner, Electrochemical Methods, 2nd ed., 2001, §6.7): the semi-integral of the current turns the peaks of a diffusion-controlled voltammogram into steps, its forward and reverse sweeps on one curve when the couple is reversible, its plateau m_L = n F A c √D: with n, the area and the concentration the node gives D. The graph: the data with the ranges, the result below (every order its colour); Zoom, Pan, Out, Rescale, the data reader and Large. Output: X (and the time), every Y and its derivative or integral of every order.',
  frft: 'The fractional Fourier transform of order a: a rotation of the time–frequency plane by a·90° (Namias 1980; Ozaktas, Zalevsky and Kutay, The Fractional Fourier Transform, 2001); a = 0 the signal, 1 the Fourier transform (centred), 2 the signal reversed, the orders adding up. The discrete transform of Candan, Kutay and Ozaktas (IEEE Trans. Signal Process. 48 (2000) 1329): from the eigenvectors of the matrix that commutes with the DFT, unitary and exact. A chirp (a frequency sweeping linearly in time: radar, sonar, ultrasound, swept spectroscopy) is spread over every frequency by the FFT, but at one order it gathers into a spike. Modes: the transform of an order (|F^a|, Re, Im against u, the samples from the middle); the scan of the orders 0 … 2 (how gathered the transform is at each, Σ|F|⁴ / (Σ|F|²)², the best order found and the chirp rate it means); a filter in the fractional domain: at the best order (or one given) a band of u around the spike (± a width, or given) taken out (a chirp interference removed from a signal, which the FFT cannot do) or kept, then back by the order −a. In the first range drawn on the graph (X even, at most 2048 points). The graphs: the data with the filtered curve over it and what was taken out below; the transform or the scan on its own axis; Zoom, Pan, Out, Rescale, the data reader and Large.',
  interp: 'Reads every Y column on a new X: a number of points or a step between From and To (empty: the range of the data), or the X on the “at” port (a column, or a dataset: its X): e.g. several curves on a common X. Methods: linear, natural cubic spline, Akima (no overshoot near abrupt changes), PCHIP (monotone between the points, no overshoot), nearest. Outside the data: empty, the end value, a straight line from the end, or the method itself. Repeated X are averaged. Output: the new X and the curves read on it. Ranges (Add a range, dragged on the graph; the same for every Y, or per Y): only the points inside them are used, the new X from the first of them to the last. The graph: Zoom, Pan, Out, Rescale (X, Y), the data reader (Reader: snap to the data of a curve, the nearest or the one chosen, or free: any place; a click keeps the reading, the arrows move it, Esc lets go) and Large.',
  normalize: 'Every Y column divided: by its maximum, its largest absolute value, its value at an X, its first point, its area (trapezoids), a value; to the range 0 … 1 (min–max); z-scores (mean 0, SD 1); or point by point by a column on the “by” port. The factor from the points between From and To (empty: all). Outputs: the normalized curves and the factors (what was subtracted and divided by). From – to can also be drawn on the graph (Add a range; its edges dragged). The graph: Zoom, Pan, Out, Rescale (X, Y), the data reader (Reader: snap to the data of a curve, the nearest or the one chosen, or free: any place; a click keeps the reading, the arrows move it, Esc lets go) and Large.',
  fft: 'The FFT of every Y column (X evenly spaced; else read on an even grid). Spectrum: the frequency (1 / the unit of X) and the amplitude (of a sine, corrected for the window), the power, dB, the phase or the real and imaginary parts; a window (Hann, Hamming, Blackman), the mean or a line removed first, zeros added up to a power of 2. Filter: low pass, high pass, band pass, band stop at cut-off frequencies (ideal or with a Butterworth-like edge of an order), the ends mirrored first (less wrap-around). Output: the spectrum or the filtered curves. More modes: the power spectral density by Welch’s method (segments with overlap, each windowed and detrended: density per unit of frequency or power, in dB), the spectrogram (the PSD of every segment in time: X, frequency and PSD as columns, a map with Contour), the coherence of the first two Y (how much they go together at every frequency, and the phase between them), the envelope, phase and frequency of a signal (Hilbert), the Allan deviation (the stability of a rate against the averaging time τ: octaves, decades or every step) and the wavelet scalogram (Morlet: the power at every time and frequency). Lomb–Scargle: the periodogram of data sampled unevenly (the generalised one, a sine and an offset fitted at every frequency, Zechmeister and Kürster 2009): the power (0 … 1), the amplitude of the sine, the false-alarm probability (Baluev 2008, as astropy) and its line at the % chosen; the frequencies from … to (empty: up to the mean Nyquist frequency), a number of points in the width of a peak. Harmonics: the fundamental (the strongest, or given) and its harmonics (their number with it; above the Nyquist frequency folded back), their amplitudes and levels in dBc, THD, SNR, SINAD, ENOB and SFDR as MATLAB’s thd, snr and sinad (a Kaiser window β 38, the power of every main lobe; the noise from the bins left); outputs: the harmonics, the measures, the spectrum in dB. Filter ▸ Design: by the FFT, or a recursive filter as in electronics; Butterworth, Chebyshev I (its ripple) or Bessel (a flat delay: pulses keep their shape), of an order; forward and backward (no phase shift) or causal. Filter ▸ notch: the mains (50 or 60 Hz) and its harmonics taken out (SciPy’s iirnotch, a quality Q). The response port: the gain (dB) and phase of the filter, also in the graph (the filter’s response). Ranges (Add a range, dragged on the graph of the data, at the end of the Graph of list; the same for every Y, or per Y): each part analysed on its own, a curve each (named after its range; the coherence: the first range); the filter works in every range on its own, outside them the data as they are or nothing (Outside). The graph: Zoom, Pan, Out, Rescale (X, Y), the data reader (Reader: snap to the data of a curve, the nearest or the one chosen, or free: any place; a click keeps the reading, the arrows move it, Esc lets go) and Large.',
  kk: 'Kramers–Kronig: the real and imaginary parts of a causal response are tied together. Impedance (EIS), the Lin-KK test (Schönleber et al., 2014): the spectrum fitted by a resistance, RC elements of time constants spread evenly over the frequencies measured, an inductance (and a capacitance if asked), linear in their values; of 1 to 50 elements, the best fit not over-fitted (μ, the share of negative resistances, at least 0.85); the residuals (data minus fit, in % of |Z|) say whether the data obey Kramers–Kronig: within about ±1 %, yes; larger, with a trend: drift, a system that changed during the sweep, non-linearity. The columns: the frequency, Z′ and Z″ (found by their names, or chosen); Z″ given as −Z″ is seen by its name or its sign. Graphs: the residuals against the frequency (logarithmic) with the ±band, Nyquist, Z′ and −Z″ with the fit. Optical: from the reflectance R at normal incidence (a fraction or %), the phase of the reflection by the Kramers–Kronig integral, then n, k, ε₁, ε₂ (and α in cm⁻¹ when the unit of X says what the wavelength is). General: the real part from the imaginary part (ε₁ from ε₂ with ε∞, χ′ from χ″), or the imaginary part from the real part. X: the values of its column as they are: any unit proportional to the frequency (Hz, eV, cm⁻¹, THz) gives the same result; a wavelength (nm, µm, Å in the column’s name) is turned into 1/λ for the integral and the results come back on the wavelengths. The integrals need the data beyond the range measured: below it R constant or Hagen–Rubens (a metal), the part zero, constant or straight down to 0; above it a power law (R ∝ ω^−4 for free electrons) or constant. These tails are assumptions: drawn dashed on the graph, past the dashed lines where the data end. The graph: Zoom, Pan, Out, Rescale (X, Y), the data reader and Large. Output: a dataset with X and the results.',
  convolve: 'Convolution and deconvolution of every Y column (X evenly spaced). The response (kernel): a Gaussian, a Lorentzian or a box of a FWHM in the units of X, or the curve on the “kernel” port (on the same step, centred on its maximum, area 1). Convolve: the data broadened by the response (the ends: zero, reflected, the end value). Deconvolve: Wiener (a regularization λ against the noise: larger λ, smoother result) or Richardson–Lucy (iterations; values ≥ 0, e.g. spectra, images): the broadening by the instrument removed. Output: the curves convolved / deconvolved. Correlation: of every Y with the curve on the “kernel” port (or with itself: the autocorrelation), as a coefficient (−1 … 1), biased, unbiased or a plain sum, against the lag in X; the “lags” output gives the lag of the largest correlation: the delay between two signals. Ranges (Add a range, dragged on the graph): each processed on its own, outside them the data as they are or nothing (Outside); not for the correlation. The graph: Zoom, Pan, Out, Rescale (X, Y), the data reader (Reader: snap to the data of a curve, the nearest or the one chosen, or free: any place; a click keeps the reading, the arrows move it, Esc lets go) and Large.',
  average: 'The mean of several curves, each with its own X: the datasets on A, B, C … (a new port appears when the last one is used), every Y of each (designated, or the list written) with its X. They are read on a common X: every X of the curves, the X of the first one, or a uniform grid (From – To: empty, the range all of them cover); by straight lines, a spline, Akima, PCHIP or the nearest point, never extrapolated; the mean is given where every curve has a value, or at least k of them. Outputs: X, the mean, SD (designated ±Y: error bars in a Plot), SE = SD / √N, N (the curves there), and min, max, median if asked. A curve whose X goes back (a loop, a scan up and down) is warned of: taken in the order of X, its branches are mixed. The graph: the curves (grey), the mean (red) ± SD (shaded). Ranges (Add a range, dragged on the graph): the mean only over them. The graph: Zoom, Pan, Out, Rescale (X, Y), the data reader (Reader: snap to the data of a curve, the nearest or the one chosen, or free: any place; a click keeps the reading, the arrows move it, Esc lets go) and Large.',
  image: 'Image analysis: an image prepared step by step, calibrated, then measured. Open an image (PNG, JPEG, TIFF of 8 or 16 bit or float, gray or RGB; the original values kept; the scale of a TIFF read when ImageJ or the microscope wrote one: FEI / Thermo, Zeiss, Tescan electron microscopes; a height map of AFM: a Gwyddion file .gwy, its first channel of heights with its size and units, or a text of a matrix or of X Y Z lines, Gwyddion’s export with its units read), paste it (Ctrl+V on the node) or drop it. Analyze opens the editor over the whole window. At the top, the task: Particles, Spots (microarray), Network, Lattice (TEM), Surface (AFM), each its numbered steps on the left in the order they are done (Particles: Prepare with the crop, the scale and the image steps; Find, one way picked among Threshold, Pixel classifier, Find like this, Segment anything and Seeds and rays, its options under it; Check: the similarity, Review, Learn from my choices, Accuracy, Refine (for Find like this as before; for every other way: Review, a click on a particle leaves it out, faint and dashed, not measured nor drawn in the figure, a click again puts it back, Put back puts back all those left out by a click; Learn from my choices, a click says a particle is not good ✗, a second that it is good ✓, a third neither, and from 3 of each a classifier learns from their size, roundness, mean, contrast with the ground around, edges, texture, nearest neighbour and how sure Segment anything is of it, and leaves out those less probable than the line on the histogram of the probabilities; Show the unsure ones outlines the 5 it is least sure of; Sure (Segment anything): the least the model must be sure of a particle, on a histogram); Measure: what is measured, the results, the arrangement, the texture. Spots (microarray): Prepare; Spots (an ellipse drawn on one, Stamp on the others, centred on their bright pixels; their groups; every spot’s background: a ring around it, its gap and width, a region drawn, the global one, Same for its group); Background (the statistic of the background, median or mean, the saturated level, the global background); Measure (on each channel, the ratio of two, the Spots sheet). A project whose selections have a background of their own opens in it. Network: Prepare, Mask, Network, Texture. Lattice: Prepare, Spectrum, Fringes, Rings. Surface: Prepare with the heights and Level, Roughness, Profiles, Step height), a step done marked ✓; on the right what was found so far (the particles: how many, their mean size and its histogram, what to do next), the tool’s options, View and histogram, Selections, Layers, Keys; the selection tools of the task at the top, More shows all of them. All tools shows every panel at once, as tabs on the right, the image steps on the left. Segment anything: a neural network finds the outline of a particle from a click (Point (SAM); Shift-click adds a part to it, Alt-click takes one off), from a box dragged around it (Box (SAM)), or of every particle at once (Everything: the model asked at a grid of points, 16 × 16 to 48 × 48; the masks it is sure of (Sure, 0.86) and that are stable (stable, 0.92: the mask hardly changes when its threshold moves) kept, of two alike the surer, a mask holding two particles left out for them, a piece of one left out; Size: the smallest and the largest, in % of the image; those on the edge left out if asked; the data bar under the image never asked). The particles found are selections as the others (P1, P2 …, in the group of particles; Everything replaces those found before). Two models: MobileSAM (general, the default: trained on everyday photos, it outlines SEM particles well) and micro-SAM EM (tiny), finetuned on mitochondria and nuclei in electron microscopy (for organelles; on SEM particles it is unsure). The model (about 42 MB) and the engine that runs it (27 MB) are downloaded from the app’s own site the first time, after you agree, and kept in this browser (Remove it from this browser takes them out); it runs on the graphics card (WebGPU) when the browser has it, else on the processor (slower: Everything on 24 × 24 points about 2 minutes); the image never leaves this computer. The image read is the original part analysed (the image steps do not change it); reading it takes a second or two, once. A long piece of work (a search, Refine, an image step taking more than a second) shows a card over the image: what it is doing, how far (the candidates looked at, the step computed), the time and the time left; Cancel stops it (an image step: Stop turns that step off); the image can still be moved meanwhile. In All tools: On the left the steps, applied in their order, each on what the steps above give: add one (+ Add a step, under Original image, by group; the threshold, the local thresholds and the trainable classifier in Find the objects), switch it on or off, move it up or down, remove it; every parameter is there (a number left empty: automatic). A click on a step shows the image up to it. Compare, at the top, as photo editors do: Edited (the result alone), Original (\\ switches; B: while held), Side by side (moved and zoomed together; Y), Split (the original on one side of a line, the result on the other; drag the line, ⇆ / ⇅ turns it); vs the original, or vs before the step (what the step shown changes). The steps: Tone (brightness, contrast, min / max, levels with gamma, curves drawn exactly as applied over the histogram of what comes into the step: a click on the graph adds a point on the curve, drag it, double-click it or drag it out to take it off, its In / Out written in the image values, a few curves ready, and for RGB the curve of all the channels, then R, G, B each; auto-contrast, equalize, CLAHE, log, exp, invert); Colour (a channel: R, G, B, H, S, V, L*, a*, b*, gray from luminance or from weights; hue and saturation; balance); Noise (Gaussian, median, mean, bilateral, non-local means, anisotropic diffusion, remove outliers, scan lines for SEM and AFM); Background (rolling ball as ImageJ, a large ball on the image shrunk as ImageJ does; sliding paraboloid, subtract a Gaussian, flat-field; level: a plane or a polynomial of order 2 or 3 fitted and taken off, the highest part left out of the fit, for AFM); Edges (unsharp mask, Sobel / Prewitt / Scharr gradient, Laplacian, LoG, DoG, Canny, Hessian ridges, Ridges as Frangi’s filter: thin dark or bright lines at several widths, the gaps between touching particles brought out; Edges subtracted: the image minus its edges, so every edge becomes a valley); Texture (local SD or variance, entropy, range, Gabor, local binary patterns); Morphology (erode, dilate, open, close, top-hat by a disk or a square; on a mask: fill holes, skeleton, distance map, watershed that cuts touching objects, Split along dark lines that cuts the mask where a thin dark line runs on the image it was made from, as between touching particles in an electron microscope image; Cut along edges that cuts it inside its objects where that image has a strong edge, dark line or not); Find the objects: Threshold (by hand or by the 16 methods of ImageJ: Default, Huang, Intermodes, IsoData, Li, MaxEntropy, Mean, MinError, Minimum, Moments, Otsu, Percentile, RenyiEntropy, Shanbhag, Triangle, Yen; light or dark background), local thresholds (Mean, Median, Gaussian, Niblack, Sauvola, Bernsen, Phansalkar) and the trainable classifier (below): the result is a mask of the objects, shown in a colour over the image. The threshold found is written under its step and marked on the histogram (on the right). The wheel zooms, a drag moves the image; the values under the mouse (the original and the result) are written at the bottom. A large image stays quick: while a value changes, the steps run first on a copy of about a megapixel (their lengths in pixels scaled with it; “preview” written at the bottom), then at full size once the changes stop; only the steps from the one changed on are computed again, a newer change stops the one running, and the file is read off the page. Crop and Scale work on the original as it came. Crop: the part analysed; drag it, or Cut the data bar (the band of an electron microscope’s settings under the image, found by itself); No crop. Calibration: Scale, draw a line along the scale bar (Shift: straight; a loupe follows the mouse; Find the bar’s ends moves the line’s ends to the bar’s when it is let go), give its length and unit, Set; or type the size of a pixel (in the editor or the options). Read the scale bar: the bar found in the image (the longest white or black bar a few pixels thick, standing out from what is around it) and its label read by OCR (tesseract.js: its engine and English data downloaded once from jsDelivr, some 5 MB; the image is read here and not sent anywhere); the proposal (the bar’s length in px, the length and unit read, 1 px = …) can be corrected, then Accept sets the calibration, Reject leaves it; nothing changes without Accept, and each image is asked once (Read again). Selections (the tools at the top, on the image analysed): rectangle and ellipse (drag; Shift: square, circle), polygon (click the corners; double-click, Enter or the first corner closes it), freehand, line and segmented line (a width for its profile), points, angle (three clicks), wand (a click on an object: on a mask the object, on an image the pixels joined to it within a tolerance; its outline on the pixels’ corners), rays (a click inside a particle: rays from there, each stopped at its first edge or at the gap to a particle touching it, give its outline as a polygon whose corners can be dragged; its size found by itself; bright or dark as the pixel clicked, or as chosen; a quick model for Find like this, + Add model), stamp (a copy of the selection picked at every click, centred on the bright or dark spot under it if asked). Picked (a click on it with the hand): moved by dragging, its handles change it (a rectangle’s or ellipse’s sides, corners and turn; the points of the others; a double-click on a point takes it off); Delete removes it, Ctrl+D copies it, the arrows move it. The ROI manager lists them: name, colour, group (a sample, a replicate), shown or hidden. A spot’s background: a ring around it, between two circles (the inner one a gap away from the spot, the outer one its width further; the other spots left out; rings draws both circles of every spot), a region drawn, or the global one (a selection or a value, in Measure); a selection can itself be a region of background. When a global background is set, every spot is also measured against it (B global, Net global), to compare with its own ring. Measure: on the original, the result or the image after a step; area, perimeter, centroid, centre of mass, bounding box, Feret (its angle, and the least width), the smallest rectangle around it (Box length and width: of a cube, its side; its orientation, 0 to 90° for a square, else 0 to 180°), the fitted ellipse, circularity, aspect ratio, roundness, solidity, corners and shape, equivalent diameter, the nearest neighbour; mean, SD, min, max, median, mode, integrated density, skewness, kurtosis; the part the mask of the steps covers. A colour image: on its luminance, or on each channel with the ratio of two (a two-colour microarray). Spots: F and B (mean, median, SD), net F − B (the background’s median or mean), SNR, net integrated density, saturated pixels. The results are shown as they change (a click on a row picks its selection; Copy for a spreadsheet). Particles (as ImageJ’s Analyze Particles): Find particles turns the objects of the last mask of the steps into selections (joined by their sides or corners), named P1, P2 … in a group of their own (particles), found again (replaced) when asked. Touching ones are cut apart if asked: a watershed on the distance map, cutting a neck at least the tolerance deep and at most 0.75 as wide as the thinner part, so a long or flat particle is not cut along itself. Round particles in clusters are cut well; angular ones touching side to side are not, and for them there are Split along dark lines (a step), a trainable classifier with an edge class, or Find like this. Particles are kept by their size and circularity, those on the image’s edge left out if asked. Find like this (template matching): draw a rectangle (or any shape) around one good particle, turn it with its handle to fit, pick it and press Find like this; every place that looks like it is found on the last image of the steps that is not a mask (the data bar of an electron microscope under the image, when not cut by the crop, left out: its dark band and white text next to the ground look like a particle’s edge), turned any way (Turns: square 0 to 90°, rectangle 0 to 180°, any), a little larger or smaller (Sizes), touching others or not, kept when the similarity (the correlation with the model, 1 the same) is at least the one given (its slider changes the particles found at once, without searching again); Around it: what is compared besides the particle, shown dashed around the selection picked (a disc around it; only the particle and its edge, for particles in clusters; the particle and the ground around it out to the dashed line, whose handle drags it, for particles on their own: one in a cluster, or a piece of the ground, is then less alike); Find more like these searches again with particles found as models too (of the surer half, as alike as the median or more and not cut by the image’s edge, the least alike: the doubtful ones near the least similarity would find more of their own mistakes); Review: a click on a particle found leaves it out, on one left out (faint red) puts it back; fit the edges moves each rectangle’s sides to the edges under it, so its side is measured, not only its place (a side the edges would make more than 30 % longer or shorter, a neighbour’s or a gap’s edge met, stays as found). + Add model puts the selection picked in a list of models, each with its own Around it, turns, sizes and group (its particles go in that group, in its colour): cubes on their own and cubes in clusters, or cubes and triangles, in one search. Its panel in sections, folded, each saying on its title what it holds: Model (the models, Turns, Sizes, Find); Compared area (Around it; a margin I draw: the dashed line around the model picked, Edit the margin shows its points on the image, dragged, one added by dragging the small ones between them, one taken off by a double-click; what is inside it is compared, nothing outside; Reset; From the outline + N px, Make: the margin made again as the model’s outline widened by N px, then edited; Pick with SAM (in Model): a click on a good particle, Segment anything gives its outline, made the model (a polygon, its points dragged), its margin the outline widened by the px given beside it; Same margin for all models: every model of the list given the compared area of the one picked; show it on the particles found: the area compared drawn dashed around every particle found, turned and scaled as it was found); Similarity (the similarity of every place found on a histogram, the least kept a line on it, moved by a click or a drag, the particles kept at once; the mouse resting on a particle found says its similarity); Separation and edges (Separate by Distance: the least distance between two particles, a part of the model’s radius, 0.75 by default; or by Overlap: two places whose outlines overlap more than a part of the smaller, 30 % by default, are one particle, better for long particles or particles touching along a side; fit the edges, only inside the margin drawn if asked); Review (a click leaves a particle out; use those left out: kept, and at the next search the places more like one of them than like the model, judged on what is compared, are dropped, so leave out mistakes, not good particles; Clear. Learn from my choices: a click on a particle found says it is not good (faint red), a second one that it is good (✓), a third neither; the places it left out as less probable are shown faint gray, and a click on one says it is good. From 3 of each a classifier learns what tells them apart, from the features of every place (how alike, its edges, brightness, contrast, size, turn, texture, its nearest), and keeps the places it finds probably good; the Similarity histogram then shows their probability, its line the least kept. Method: Logistic regression, LDA, k-NN, Random forest, Naive Bayes (Gaussian), SVM (an RBF kernel, its probability by Platt’s sigmoid) or Boosting (gradient boosted trees), all as scikit-learn’s, or Auto: the one most often right on your examples, each left out in turn and guessed from the others (past 30 examples, ten parts of them in turn; worked out off the page, so a click stays quick; each method’s part right is written); the bars say how much each feature counts. Show the unsure ones outlines the 5 places it is least sure of, to be said next; Forget the examples); Accuracy (mark by hand every true particle of a part of the image, as selections in one group, truth by default, then Check: of the particles found in the box around them, precision is the part right, recall the part of the true ones found, F1 both; for any way of finding them); Pixel classifier (the trainable classifier of the steps, shown here too: + Add a pixel classifier adds it as a step, Open its step shows the image up to it); Advanced (Compare: Brightness, the values, best in noise; Edges, the directions of the outline, best when the insides of the particles differ, hollow, shiny or textured; or Both. Preset Fast, Balanced or Precise; the turn step, the sizes tried, the model’s radius in the first quick search, the candidates looked at closely, the image compared, after a step, the edge band, the most found, the brightness counted or not; each marked when changed, with ⟲, Reset all; how long the search took is said; for a large model the first search runs by the FFT, chosen by itself when quicker). Particles ▸ From: the mask, or seeds and rays (a seed in every particle, from the mask’s centres or, without a mask, the bright or dark blobs of the image at the particles’ size; from each, 32 rays stopped at the first edge: touching particles found one by one, a dark gap between them or not). Refine: every particle found made the regular shape most like it among those ticked (circle, ellipse, square, rectangle, triangle, hexagon), its place, size and turn fitted, snapped to the edges under it if asked; each can then be moved, turned or resized by hand, and a particle changed by hand (✎) is left as it is when refined again (Refine all: those too). Frequency: Image ▸ View shows the image or its FFT spectrum (its 2D Fourier transform, the zero frequency in the middle: a periodic pattern makes spots at 1 / its period from it), on a log scale or linear, with a Hann window against the edges, of the result or of the original; the radial spectrum (the power averaged in rings, against k and d = 1/k, with the distance of its strongest peak) goes to the workbook if asked. Steps of the group Frequency: Band-pass (structures larger and smaller than two sizes taken out, as ImageJ’s Bandpass filter, stripes along a direction too) and Spectrum mask (spots picked in the Lattice tab taken out, a periodic noise, or the only ones kept: a Bragg filter, the lattice alone). Lattice (TEM; a tab): with the spectrum shown, a click on a spot moves it onto its peak (its mirror taken with it): its d (the distance of its planes, in the calibrated unit) and their direction; between two spots, the angle of their planes; Bragg filter puts the spots into a Spectrum mask step (only they kept: the lattice alone, its fringes clean), Take them out the opposite (a periodic noise). Fringes: along every line selection drawn across them, their period (the strongest frequency of the profile; of two sets about as strong, the finer) and how many. Diffraction rings (SAED): the image a diffraction pattern, its centre found where it is symmetric (or set), its radial profile and the rings in it; with the reciprocal size of a pixel (1 px = … 1/nm, from the camera length) every ring its d, matched with the reflections of the phases ticked (Au, Ag, Cu, Pt, Pd, Al, Ni: fcc; Si: diamond) or of d values of one’s own, with the difference in %; the rings drawn over the pattern, named. Sheets FFT spots, Spot angles, Fringes, Rings, Radial profile. Surface (AFM; a tab): the image as heights, their unit and what one value is (read from a height file); the roughness is from the mean plane, so level first (Level, Scan lines). Roughness (ISO 25178) of the image and of every area selection: Sa, Sq (the mean and rms height), Sp, Sv, Sz (the highest peak, the deepest valley, both), Ssk, Sku (skewness, kurtosis), Sdq (the rms slope) and Sdr (how much larger than flat, %), these two when the heights and the calibration are lengths. Profile roughness (ISO 4287) along every line selection: Ra, Rq, Rp, Rv, Rt, Rz (the mean of the largest height in five parts), Rsk, Rku, from the profile’s mean line: straight, or a Gaussian filter of cut-off λc (ISO 16610-21) taking the waviness off (the profile at least 2.5 λc long). The height histogram with the material ratio (the Abbott–Firestone curve), the radial PSD (∫ PSD 2πk dk = Sq²), the autocorrelation with the correlation length (1/e), Sal (where it falls to 0.2) and Str (near 0: one direction, near 1: the same every way). Step height: the mean heights of two area selections and their difference, with its standard error. Sheets Roughness, Profile roughness, Height histogram, PSD, ACF, Step height; the matrix output carries the heights in their unit (to a Plot 3D: a surface). The editor’s side has its panels: Image (the histogram, the view, the crop, the calibration), Objects (selections, particles, Find like this, Refine, layers, Arrangement), Structure, Lattice, Surface and Results (what is measured, the tables); the size of a pixel is shown above them. Structure (nanoporous metals, nanowires, fibres, networks): the last mask of the steps (not a skeleton step) thinned to its skeleton, the skeleton made a graph: its junctions (where three branches or more meet) and free ends are its nodes, the lines between them its branches; the spurs (short branches to a free end, from the bumps of the outline) cut, shorter than a share of the thickness at their junction (1 by default) or than a length; every ligament (a branch between two junctions) measured: its length along the skeleton, from the centres of its junctions or from their surfaces (their radii taken off), its thickness from the circles inscribed on its middle (the median, the mean, the neck), its straightness and direction; the branches cut by the image’s edge left out of the statistics if asked; the pores (the holes of the mask), each its area and its largest inscribed circle. Sheets Network (the numbers: solid fraction, ligaments, junctions, the mean, SD and median of the lengths and thicknesses, the skeleton length and junctions per area), Ligaments, Junctions, Pores in the workbook. Over the image: the branches coloured by length, thickness or type (dashed: on the edge; faint: not counted), the junctions white, the free ends red. By hand: Select (a click on a branch shows how it was measured: its path, its inscribed circles, its length step by step; Delete, Keep: never cut as a spur, Leave out: not in the statistics; a node dragged moves it, dropped on another merges them), Draw (a branch that is missing, its ends joined to the skeleton near them), Erase, Add node (on a branch: two ligaments). The changes by hand are kept as places, so they apply again when the mask changes; Undo, Reset hand edits. Learn from my edits: the cut of the spurs learnt from the spurs you deleted and the short end branches you kept, then used on the whole image. Also in Structure: Grain size (ASTM E112): test lines over the mask (a grid of horizontal and vertical lines, or three circles), the boundaries they cross counted (the mask the boundaries, or the grains with the boundaries between them; a crossing at a line’s end a half), the mean lineal intercept ℓ = length / crossings for each direction and for all, the ASTM grain size number G = −6.6439 log₁₀ ℓ(mm) − 3.288 and the grains per mm²; the lines and their crossings drawn over the image if asked. Orientation (as OrientationJ): the structure tensor of the gradient averaged over a window σ, at every pixel the direction of the structures and its coherency (1: one direction, 0: none), the dominant direction of the image (counter-clockwise from the x axis) and its coherency, the distribution of the directions (each pixel weighted by its coherency); the image coloured by them if asked (the hue the direction, the saturation the coherency). Fractal dimension: boxes of 1, 2, 4 … px over the mask or its edges, D the slope of log N against log 1/size, with R². Sheets Grain size, Orientation, Fractal. Arrangement (Objects tab): how the particles found lie, of all of them or of one group. Every particle: its nearest (centre to centre, edge to edge), the mean distance to its k nearest, its Delaunay neighbours (the particles it faces: its coordination), its Voronoi cell (the area nearer to it than to any other), its hexatic order ψ6 (1: its neighbours at 60°), its cluster (particles nearer than the cluster gap, edge to edge). All of them: the density, the mean and SD of the nearest distances, Clark–Evans R with z and p (Donnelly’s edge correction: R near 1 random, below 1 clustered, above 1 regular, 2.15 hexagonal), the mean coordination, the spread of the Voronoi cells, ψ6, the clusters, the first peak of g(r). Curves: g(r), the pair correlation (its peaks: the distances the particles keep), and Ripley’s L(r) − r with the band of points at random (above the band: clustered at that scale, below: regular), the nearest distances against those of points at random. Over the image (Show): the line to every particle’s nearest, coloured by its length (its value written if asked), the Delaunay links, or the Voronoi cells coloured by their neighbours (5 red, 6 green, 7 blue: the defects of a hexagonal layer). The sheets Arrangement, Neighbours, g(r), Ripley L and NND distribution go to the workbook: analyse them with the other nodes (Histogram with a log-normal fit, Descriptive statistics with D10, D50, D90, a Plot of g(r)). The editor’s left and right panels are as wide as dragged by the bars beside the image (double-click: as they were). Layers (a toggle, an estimate): where two particles touch, the one whose outline stays whole is on top, the one cut by it under it (else the brighter on top); every particle its layer (1 when nothing lies on it), its outline in the colour of its layer, a Layer column. Several models (particles that look different, lit otherwise or tilted): give them one group in the list and pick one of them; each place found is given the model most like it. Group by shape puts each in the group of its shape (circle, ellipse, triangle, square, rectangle, polygon, irregular), told by its roundness, its corners and the area of the ellipse of its moments, and colours it; Group like the examples: give a few particles groups of your own, the others go to the group of the most alike. Nearest neighbours: centre to centre and edge to edge (a Distances sheet), their CV and Clark–Evans R in the Summary (1 random, below clustered, above regular); the orientations: their mean and the alignment (1 all alike, 0 every way). Trainable classifier (a step, in Find the objects, also shown in Objects ▸ Pixel classifier; as ImageJ’s Trainable Weka Segmentation and ilastik): click a class in the step (or press 1, 2, 3 …: its row is marked) and paint on the image with one of its tools: Brush (paints the class under its circle, which follows the mouse), Fill (draw around a particle or a piece of the ground: its inside painted), Eraser (takes the paint away under its circle, and an example drawn as a selection it touches); their size: the slider (1 to 100 px of the image), [ and ], or Alt and the wheel; the paint is drawn over the image in the colour of its class and kept in the node; the classifier learns when a stroke ends (Live update; off: only at Update now); a class’s row says how many pixels are painted, its eraser takes all of its paint away; Ctrl+Z undoes a stroke; any selection drawn while a class is picked (the wand, a polygon …) is an example of it as well (one drawn before: pick it and + picked). Mask of, under the classes, says which class the mask is made of (object unless chosen). Use the N particles found as object examples: the particles of Find particles or Find like this become examples of the object (and their ring the edge). The classes: object, background, edge (the rim just outside a particle and the line between touching ones, which teaches it where one particle ends) and any of your own. Edges from outlines (on by default, 2 px): outline a few whole particles with the wand or a polygon as examples of the object, and the ring just outside each, with the gap where two outlined ones touch, is taught as the edge class by itself; nothing to draw along the edges. A learner learns the classes from the pixels’ features at several scales (smoothed, gradient, Hessian, difference of Gaussians, local variance, up to large particles; a colour image: its channels too); Method: a random forest (as Weka and ilastik), extra trees (thresholds drawn at random: quicker to train), boosted trees (tree after tree on what the others got wrong, as LightGBM) or a small neural network (24 units), or Auto: each trained on three quarters of the example pixels, the one most often right on the quarter kept out (said in the step’s note); to split touching particles by an edge class the forest and the extra trees are best (the others are so sure of the object that thin gaps fade). The features are kept for the next examples, so a new stroke costs only the training. Its output: a mask of the target class; objects split by edges (seeds where the object is sure, grown over the object and the edge, two particles meeting on the edge’s crest and kept apart by a line: clusters of touching particles come apart, then Find particles without Separate); the target’s probability; or where it hesitates (Where it hesitates, in the step: bright where an example teaches it most; again: back to the output). The same examples give the same mask; the examples are not measured, and a particle found made an example stays when the particles are found again. Test images of particles (clusters of discs, shapes, all of them mixed and touching, grainy ones, nanocubes touching side to side): the project’s test-images folder (npm run test-images makes them). Outputs: matrix, the result (gray; RGB: its luminance) with X and Y in the calibrated unit, for a Contour / heatmap or a Matrix; figure, the image on a page of its proportions (its width in mm; the result, the original, or the original with the mask over it; a colour table; the selections’ outlines and names; a scale bar of a round length or the one given), for a Merge, a Figure Drawing or the insets of a Plot, exported as a Plot is; workbook, the measurements: Selections (a row each), Spots, Distances, Profiles (along the lines), Points, Summary (by group and all: count, area together, the mask’s coverage, mean and SD of every measurement, the orientation and alignment; the image’s coverage), the units of the calibration in the columns’ names. The algorithms are checked against scikit-image and scipy (npm run check).',
  phasediagram: 'A binary phase diagram computed from a thermodynamic model, for teaching. Two components A and B (the composition axis: at% B); for each its melting point and its enthalpy of fusion; the interaction of the liquid and of the solid (Ω, kJ/mol: 0 an ideal solution, complete solubility as Cu and Ni; a large positive Ω of the solid opens a gap in the solid, two solids α and β, and with the liquid a eutectic; Ω₁ makes the interaction lean to one side, Ω = Ω₀ + Ω₁ (1 − 2x), so one solid dissolves more than the other). System chooses an example (Cu and Ni, ideal; Pb and Sn, Ag and Cu: models fitted so the eutectic and the solubilities at it come out near the real diagram, a minimum and a gap in the solid like Au and Ni: teaching models, not assessed data). The diagram is the lower common tangent of the free energies of the solid and the liquid at every temperature: the regions coloured (two phases: their colours mixed and hatched), the liquidus, solidus and solvus, the eutectic line and point written, the phase names in the regions. Lever rule: Place points, then a click on the diagram adds a point (drag it to move it), or type its composition and temperature; at each point the tie line is drawn to the two phases and their compositions and amounts are written (the amount of α is (x of β minus x) over (x of β minus x of α)). Cooling an alloy: its composition; a dashed line down the diagram, the first solid and the last liquid marked, and a second figure: the amount of every phase against the temperature, stacked (the temperature falling to the right); above the eutectic, the primary phase and the liquid that becomes the eutectic. Outputs: the diagram and the amounts (figures, for a Merge or exported), the points (phases, compositions, amounts), the amounts on cooling and the lines, as tables.',
  digitizer: 'The values read off the image of a graph. Open an image, paste one (Ctrl+V on the node) or drop it; it is kept in the project (a large photo made smaller: 3000 px at most). Axes: three calibrations: 2 points on each axis (X₁, X₂ on the X axis, Y₁, Y₂ on the Y axis, each with its value: the image may be turned, the axes not perpendicular); the 4 corners of the frame with the X at the left and right edges and the Y at the bottom and top (a page photographed at an angle: the perspective corrected); many reference points with their X and Y: ticks, crossings of the grid, corners, six at least, spread over the graph (a curved page, a lens): a thin-plate spline through them, or a polynomial of degree 2 or 3; every point shows its error in % of the range (red above 1 %: a click to check). Log X / log Y for logarithmic axes; the X and Y titles name the columns. A calibration point is dragged, or moved with the arrow keys (1 px; Shift: 0.1 px) after a click on it; the Magnifier (a button: on or off) shows the pixels under the mouse beside the cursor, enlarged, with the points placed, the values under the mouse are written at the bottom. Sets: as many as you need (a name, a colour); the active one receives the points: Points (on from the start; each drawn as a + whose arms follow the X and Y of the graph (turned with a turned image), its length and line set under the sets): a click adds one, drag moves it, a double-click removes it; Error bars: a click above or below a point places the upper or lower end of its bar (±Y: half of the bar, or the one end given). Auto: the Pipette takes the colour of the curve, then Find points looks for it (tolerance %) in the area drawn (Area: a rectangle, Lasso: by hand; Exclude: parts left out; text, the legend; none: the whole image): a curve gives a point every N pixels across (following the curve it is on where another of its colour crosses it), markers give the centre of every blob of the size given; the points of the active set in the area are replaced. The wheel zooms around the mouse; the middle button pans; Large opens a big view. Copy image to a new Digitizer: another panel of the same figure. Output: X, Y (and ±Y) of every set, in the order of X or as placed.',
  eis: 'An impedance spectrum fitted with an equivalent circuit (as NOVA or ZView). Data: a dataset (or a sheet of a workbook). Columns: what each column holds, by its role; the Frequency column (in Hz, f, or in rad/s, ω = 2πf: values that look like ω are pointed out, 0.628319 = 2π · 0.1), the Z′ (real part) column and the Imaginary column, which contains Z″ or −Z″ (auto: −Z″ when its values are mostly positive); or |Z| and the phase (°). Each is guessed from the names (Freq, Z′, Re, −Z″, Im, |Z|, Phase …) and shown with its first values; a column taken only by its place (names A, B, C) is marked to check; columns without a name are shown and chosen by their letters. A workbook in: Sheet, at the top of the options, chooses the sheet. Circuit: one of the list; Randles (simplified R(RC), classic R(C[RW]), with a CPE R(Q[RW])), two time constants, a coating, diffusion, an inductive lead, supercapacitors (a porous electrode, de Levie: RWo; R(RQ)WC): or written in Boukamp’s circuit description code: elements one after another in series, ( ) a parallel group, [ ] a series group inside it; the elements R (Ω), C (F), L (H), Q a constant-phase element (Y0 in S·sⁿ and n: Z = 1/(Y0 (jω)ⁿ)), W the semi-infinite Warburg (Y0: Z = 1/(Y0 √(jω))), Wo and Ws the finite-length Warburg, open and short (R and T: R coth √(jωT) / √(jωT), R tanh √(jωT) / √(jωT)); numbered by kind (R1, R2, Q1) or as written (R1(R3Q1)). Or built on its drawing, in the options or large (Large): drag an element of the palette (R, C, L, Q, W, Wo, Ws) onto it: on a side of an element in series with it (left, right) or in parallel (above, below), on its middle in its place; on the edge of a group, beside the whole group; drag an element already there to move it (it keeps its name; on the middle of another one the two change places), out of the drawing to delete it. ⑂ split and ⑃ join: drag the split onto the first element of a line in series, the join onto the last (or both onto one element): the elements between them become one branch of a parallel group, and its other branch waits, dashed (drop here), for an element dragged onto it (new, or moved); Cancel or Esc takes them off. Or click a part (Group: the group it is in; none: the whole circuit), then + series, + parallel, Replace or Delete. Undo. The code follows, with the numbers when they are needed, so every parameter keeps its name. Its figure (the circuit output): the classic symbols (a zigzag resistor, the plates of a capacitor, the bent plates of a CPE, the loops of an inductor, the box of a Warburg) on a white or transparent page, the fitted values under the elements or not (drag them on the figure where they read best: kept; ↻ Values puts them back); exported as it is (SVG, PNG …) or taken into a Figure Drawing, an inset or a Merge. Parameters: the start of each (empty: guessed from the data; R₀ the high-frequency intercept, the arcs the width of the spectrum shared, their capacitances from the apex 1 / (2π f R), n = 0.9: Guess from data guesses them all again), fixed or fitted; Use the fit as start. Fit ranges: the frequencies fitted; every point, or ranges, as in Fit: Add a range, then drag on the graph (against the frequency (|Z|, Phase, Bode) the band drawn as you drag; on Nyquist the same band across Z′, its edges at the Z′ of the range’s first and last points, each snapping to a point of the spectrum), the button then off; the edges of a range dragged at any time; or typed (From, To in Hz); All frequencies: none. The points outside them drawn pale. A fit per range: each range fitted on its own too, with a circuit of its own (empty: the node’s; e.g. the high-frequency arc alone with R(RQ)), drawn dashed over it, its values listed: Use as starts makes them the starts of the whole circuit (its parameters of the same names); the “fits per range” output: a row per parameter. Auto fit (on): the fit at every change; off: only on Start fit; the result stays until then, and a change of the settings is said (Start fit fits again). The fit: complex nonlinear least squares on Z′ and Z″ at once (Levenberg–Marquardt on the logarithms of the parameters: positive, any scale; n kept in 0 … 1), weighted by the modulus |Z|, proportionally (each part by itself) or not at all; the values ± their standard errors and % errors, χ², the reduced χ² and R² (Z′ and Z″ together, and each alone). An element the fit has no use for: its impedance gone to 0 or to ∞ over the spectrum (a parameter run away: W1 Y0 → 10³⁰⁴); is named, with the circuit without it to try; a CPE whose n went to 1 is a capacitor. The graph: Nyquist (−Z″ against Z′, equal scales), |Z| or the phase against the frequency, or both on two axes (Bode); the data, the circuit fitted; the tools of the other graphs: Zoom, Pan, Out, Rescale (X, Y), the data Reader (off until its button), Large. The frequencies are written beside the points (one a decade, every point, or none) and their values too (Values); drag one where it reads best: it stays there, in the figures too, with a thin line back to its point when it is far; Labels puts the graph’s back. A click on a point selects it (an orange ring; again: no more), a rectangle dragged selects every point in it (Shift: no more); then Leave out selected takes them out of the fit (grey, crossed), Take back selected puts them back, Clear selection; Restore all: so a click alone never changes the fit. Outputs: parameters (a row per parameter: value, ± SE, error %, unit, fixed; then χ², reduced χ², R²), fits per range, fitted (the frequency, the data and the fit (Z′, −Z″, |Z|, phase), the residuals, used or left out: a row per point), fit curve (the fit drawn smooth, 25 frequencies a decade: Z′, −Z″, |Z|, the phase) and circuit (the schematic, for a Merge, a Figure Drawing or an export). Nyquist and Bode are drawn by a Plot from fitted (the data as points) and fit curve (the line of the fit); projects made before keep their graphs as such Plots.',
  phasedigitizer: 'A phase diagram read off its image, with the lever rule. Open an image, paste one (Ctrl+V on the node) or drop it. Axes: calibrated as in the Digitizer; 2 points on each axis with their values (X₁, X₂, Y₁, Y₂: placed in turn after the image is opened), the 4 corners of the graph (perspective), or many reference points (a curved page); Log X / Log Y. The X axis: its name (a component, e.g. Ni, or any quantity) and its unit (any: wt%, at%, a mole fraction, K …; or none); a binary diagram can name the other component, its amount the rest to the total in the tables (100 for a unit with %, 1 for a fraction; Total asked when the unit does not tell); with wt% or at% and the molar masses of both components the compositions also in the other unit; the Y axis: its name and unit. The tools (each moves only its own things, so a click never takes something else): Select: the points, the notes, the names of the regions and the points of the boundaries (a double-click on a boundary puts a point there, on its point removes it); Axes: the calibration points; Frame: the corners of the frame of the diagram (from the calibration, or clicked in turn when there is none: bottom left, bottom right, top right, top left; Place again in the options: anew); the ends of the boundaries on the frame follow its edges. Draw boundary: the phase boundaries, only lines (all drawn alike, in black: the colours are those of the regions); click their points one after another; a double-click (or Enter) ends one, on its first point it closes (Closed: an island, a dome); the next click starts another; Backspace takes the last point back; near a corner, a point or a line a point is caught on it (the orange ring; Alt held: not; Catch within, screen px). Straight pieces, or Smooth: a curve through the points that never swings out of them, a corner where it turns sharply (more than 60°); a right click on a point (a square: a corner) makes it a corner or smooth. When not drawing, drag a point to move it. Invariant: the line is a eutectic, eutectoid, peritectic … line; Constituent names what forms on it (eutectic, pearlite; else the name of the line). Regions: Draw regions finds the faces the boundaries close with the frame (a boundary ending short of another line or past it is closed onto it) and gives each face without one a region: a name (rich text: α + L, \\gamma), a colour, an opacity, its phases (1 or 2; auto: from the name; “α + L” two, another name one, none or R1, R2 … two); a region is the face its label is in, so it follows the lines as they move: drag the label to move it (or into another face). Points: Add point, choose its kind (the row under the tools, or in the options; changed later in the list), then click in the diagram. Lever rule: the tie line at its temperature runs to the frontier of its region left and right (the lines around it and the border; a loose line inside the region does not stop it; straight in the data, also on a turned or curved page); the phases are the regions past its ends, their compositions and amounts are written; its two arms in their colours (a: the point to the left end, b: the right end to the point; the colour of each chosen in the list, else that of the point) with their lengths: the amount of the left phase is b / (a + b), of the right one a / (a + b); dashed lines drop to the bottom of the border with the compositions. A point in a region of one phase (Phases 1, or named without “+”) gives 100 %. While the calibration is not complete, the board says what is missing. Read: only the region there and the values (a one-component P–T diagram). Path ↓ / Path ↑: from the point down (cooled) or up (heated, compressed) at its X to the border: the boundaries crossed with their values, the phases between them (L → α + L at 225 → α + β at 183), and at an invariant line the microconstituents: the lever rule just before it, with the compositions at its temperature (the primary phase and the constituent, e.g. primary α and eutectic, proeutectoid ferrite and pearlite), and just after it (the phases in all). Annotate: a text, an arrow, a line or a box. The wheel zooms around the mouse, the middle button pans, Magnifier shows the pixels under the mouse, Large opens a big view; the arrow keys move the item chosen (1 px; Shift 0.1 px), Escape ends a tool. Outputs: dataset, the lever rule and the points read (a row per point: X (and the other component, the other unit), Y, each phase with its X and its amount, the arms a and b); workbook, that table, the paths (a row per stretch between boundaries), the microconstituents and a sheet per boundary (its points along it, in the data); figure, the diagram drawn again in its data (the regions, the boundaries, the tie lines with their arms, the paths, boxes with the results, the notes) for a Merge or an export.',
  filterrows: 'The rows of a dataset (every column with them): kept, merged, sorted, thinned. A workbook: Sheet, at the top, chooses one sheet (a dataset out) or every sheet (the same settings on each, a workbook out). Rows kept: all, ranges (of the row number or of X), a list (3, 7-12, 50-end) or where: conditions chosen, no code (a column, a comparison such as < ≤ = ≠ ≥ > or between, a value; is one of: 2, 5, 7; is empty, is not empty), all of them true or any one; or written as a formula of x, the columns A, B, C …, row (the row number, also i) and n (x > 450 and B < 2; row % 2 == 0: the even rows). A condition can also be on the row number (row number ≥ 10). Of them: all, the odd or the even rows (by their row number), with any choice (List 1, 2, 10-67, then Even). And a formula: a formula true on the rows chosen too, with any choice (All, then x > 0 and row % 2 == 0). Split into parts: the rows that come out cut into parts, each its name and its conditions (x < 0, x > 0, the row number …) or its formula, an output of its own; the rest as a part too if asked; all the parts as the sheets of a workbook (parts), and side by side in one table (side by side). Empty rows (empty in every column; a 0 is a value): kept or removed. Repeated values (of X, of a column chosen, or of several columns together, like the same sample on the same day): kept, the first one only, or merged (the numbers averaged). Sort: rules applied in turn (+ Sort rule). Each moves whole rows (every column with them) or only some columns (one, or a list: 2, B-D, names; the others stay in place), and is: sorted by columns (by one, then rows with the same value by the next, and so on), each column by its own values, or reversed (the last row with data first; empty rows at the end of a sheet stay at the end). Numbers, or text in its natural order; smallest or largest first; empty values last. E.g. A and B sorted by T, then C on its own. Then only the first or the last N rows can be kept, for example the 5 largest values. One row in every N. All of it is in Options, in this order; the node shows how many rows remain.',
  clean: 'Clean the columns chosen (empty: the Y columns). Missing values (a row with an X but no value): kept, the row removed, or filled; by straight lines or a spline along X, the previous or next value, a constant, the mean of the neighbours. Outliers: further than k scaled MAD from the median (k = 3), beyond k IQR from the quartiles (k = 1.5), further than k MAD from the moving median (a window of points: for curves), Grubbs repeated, or GESD (Rosner: up to 10 % of the values), at α; then masked (kept, grey, left out of the analyses), their rows removed, replaced (by straight lines from their neighbours, or the median around them) or clipped to the bounds. Outputs: the data cleaned, and the changes (row, column, old and new value, why).',
  pick: 'Values read off every Y column (with its X) by rules: from a dataset, or a sheet of a workbook (Sheet, at the top of the options; also for the sheet shown of an Import or a Workbook): at X = a value, a list (0.2, 0.5) or a range (0:0.1:0.8): Y and the other columns read there (at every crossing of the value); at Y = …: the X where the curve crosses it; maximum and minimum: between limits on X if given, refined between the points by a parabola; rows where a condition holds (x, y, i, n, the columns A, B, C …). A curve that goes and comes back is cut first (Split into columns ▸ where X changes direction). Between points: linear, spline or the nearest point; outside the curve: nothing, extrapolated, or its end value. Output (Table): one row per point found (the Y column (its block value when cut by Split into columns), the rule, the value asked, the row found, X, Y, and with one Y the other columns read there if asked: Also read: none, all, or a list) or one row per curve (Y column), its points side by side.',
  convert: 'Text read as numbers, or numbers written as text. Connect a table (or a workbook: every sheet). To numbers: the columns written (2-6, B-F, names) or, left empty, those whose text looks like numbers (listed in the node, with examples, before anything is converted). The rules: the decimal separator (found by itself, a point or a comma); thousands separators left out (1 200,5 · 1,200.5); a unit after the number (300 K: 300, and “(K)” goes into the column’s name when every cell has the same unit); percents (25 %: 25, or 0.25); a value and its error (1.23 ± 0.05, 1.23(5): the error in a column of its own after it, designated ±Y); limits (<0.01: empty, the limit, or half of it); powers of ten (3×10^-4, 3·10⁻⁴); the first number of any text (Sample_300K: 300; off unless ticked). Marks of no value (n.d., NA, LOD, a dash) are left empty; the cells that cannot be read are left empty and listed. To text: the numbers written with a format (as they are, N decimals, N significant digits, scientific), a decimal comma if asked, and a template (“{v} V” gives “-0.5 V”): categories for a Bar chart, a Box plot or an ANOVA when the groups are coded 1, 2, 3. A worksheet (Import, Workbook) also offers to convert a column whose text looks like numbers, below the table.',
  transpose: 'Transpose (rows ↔ columns): rows become columns and columns rows; one node either way, twice gives the table back (found also as Rows to columns and Columns to rows). Every row becomes a column, named from a column of the table (Names from: the first, another one, or the row numbers); a number is written by the format and the template (“{v} V” gives “-0.5 V”). The old names of the columns become the first column (First column: as text; the number in each name, “400 nm” gives 400 and the column is named “Value (nm)”, or after what the names share, “Wavelength 400 nm” gives “Wavelength (nm)”; or left out). When the names are numbers, every new column keeps its value (Voltage (V) = -0.5): a Fit, Pick points or a Plot of these columns give their results against it, as with Split into columns. Text cells stay text. A workbook: every sheet turned (out: the first, book: all).',
  stack: 'Columns put one under the other: a long table of the name of the column each row came from, its X and its value (and the value’s error when the columns have a ±Y next to them). The reverse of Split into columns, and the layout of indexed rows that the statistics nodes, Box plots and grouped Plots read. Columns: 2-6, B-F, names (empty: every Y); their X: one column for all (the designated X, or the one named), the X on the left of each, or the row number. The name of each column kept as text, or as the number in it (“300 K” gives 300, and the column is named after what the names share and their unit). The names of the new columns can be written (empty: found). A workbook: every sheet stacked (out: the first, book: all).',
  unstack: 'Cuts one long table into blocks laid side by side: the one place where data is cut into pieces. A file of optical constants with wl, n and then wl, k written under it gives wl, n, k; a sweep saved as one table (λ, R for every thickness) gives λ and one R column per thickness; a scan that goes and comes back gives a column per cycle or per piece. X: the X of the curves (the designated one by default); Columns: the ones cut (empty: all the others). Split: where a block ends, auto (at the lines where X is not a number, else where it starts again), at text / empty lines, where a column starts again, by the equal values of a column, where its values repeat, every N rows, the cycles of a scan (it returns to its start), where it changes direction (the pieces going up and coming down), or where it jumps (changes from one row to the next by more than a value: empty: 5 × its usual change, any change when most rows repeat the value before); the rules that look at a column have it beside them, after “in” (X unless chosen: a scan’s potential while X is the time; a run number; by a column, the column whose values make the blocks). Cycles: Starts at: where the scan started, every upper turn, every lower turn, or where it crosses a value going up or down; Halves: each cycle cut into its way up and its way down (cycle 2 · up). Cycles and directions: Incomplete: the pieces that are not whole (the scan started or stopped on the way; marked * in the list, dashed on the graph) kept, left out or joined to the block next to them; Turns: a turn counts when the column goes back by more than this % of its range (0.5; larger for a noisy measured potential). Again: split each block again by a second rule (e.g. a file of several samples, each with three cycles: by the sample’s column, then the cycles in each). X columns: one X shared by all the blocks, or an X for each block. The list shows every block (its number, name, rows, X from – to): a tick keeps it (Keep all: every one again), and its name is typed there: the column of a block named takes the name (several Y columns: “n · name”, “k · name”); a block not named: the header written over it, the value of the block (“R · d = 150 nm”), else numbered (“R · 1”, “R · 2” …; a node of an older project keeps “R”, “R_2” …). The rows used are dragged on the graph (Rows) and shown as a chip under the options (✕: all the rows); names written in a list by an older version show as a chip too (✕: name the blocks in the list instead). The graph: the column of From along the rows (each block in its colour, the rows not used shaded, the cuts as lines (of the rule solid, by hand dashed red), the block numbers over them), or the curves (a Y over X, block by block); a block left out grey. Zoom, Pan, Out, Rescale, Reader, Large; Cut on Y: a click puts a line across the graph at that value (along the rows: the column the blocks are found from; on the curves: the first Y): the data are cut wherever they cross it, going up, down or either way (chosen in its chip under the options, with ✕ to remove it); the line dragged up or down moves it, a double-click or a right-click removes it; its cuts are drawn dotted in its colour; Cut on X: a click puts a cut where the diamond shows; a cut line dragged moves it, a double-click or a right-click removes it (a cut of the rule too); Snap: where a cut placed or dragged lands: data (the nearest data point), max & min, max or min (the nearest one within reach: along the rows where the column turns, a scan’s vertices; on the curves the peaks of the Y drawn, with the tolerance of Turns: else the nearest data point), off (the row under the mouse; Alt: off while held); Blocks: a click keeps a block or leaves it out; Rows: drag across the rows used. Cuts by hand: listed under the options, each with ✕ to remove it (a cut of the rule taken away: ↺ puts it back), Clear: the rule’s blocks again; a scan’s blocks share the point between them, so a cut there goes in both; after a cut by hand the blocks are numbered again; when the table has another number of rows than when they were placed, a warning. X out: one X for all blocks (a warning when another block has other X values) or an X before every block. Names: automatic: the header written over the block (k), the value of the block (R · cavity d = 150 nm, Current (mA) · cycle 2), else name_2 …: or your own list (n, k). Every new column keeps the value of its block: a Fit, Pick points or Integrate of these columns give their results against it, a Plot colours its curves by it. Outputs: the dataset (designated); long: every row of the blocks kept, once, in the table’s order, with its block number (and its cycle or segment, and the way the column goes there: up / down), to colour or filter by block.',
  combine: 'Columns, datasets and workbooks put together: connect them to A, B, C … (a new port appears when the last one is used). Result says what comes out. One column: the inputs one under the other: one after another, interleaved (A₁ B₁ C₁ A₂ …), into the first after a row, or sorted by value (smallest or largest first; the same value: all kept, the mean or the first); a dataset gives the column chosen on its row (else its Y); its name chosen here; a column out. Side by side: the columns next to each other (renamed if you wish: Names, comma-separated), the shorter ones end in empty cells, a name met twice becomes “name (2)”; a dataset out. Side by side, in sheets: every input goes to the sheet written on its row (the same sheet: side by side); a workbook out. Into a table: Into chooses the table (a dataset, a column, or a sheet of a workbook, whose other sheets are kept); every other input, in turn: its columns at the end, at the start, after, before or instead of a column of the table, or its column under a column (continuing it), above it, into it after a row, or interleaved with it; a dataset out, or the workbook. Tables one under the other: the rows of the datasets one after another, interleaved, after a row, or sorted by a column; the columns matched by their name (a missing one: empty cells) or by their place; a dataset out. The inputs are listed in the order they are used: drag ⠿ to change it (e.g. A, C, B); a workbook: its sheet on its row. Masks and designations are kept. Output “source” (one column, tables): which input every row comes from (1 = A, 2 = B …). Split into columns ▸ by a column undoes the combination.',
  python: 'Python in the browser (Pyodide: nothing is installed and nothing leaves the computer; the first run downloads Python, about 10 MB, then kept by the browser). The libraries are loaded when the code imports them: numpy, scipy (optimize, stats, signal …), pandas, matplotlib, statsmodels (regression, GLM, survival: Kaplan–Meier, Cox), scikit-learn (machine learning), scikit-image, OpenCV (import cv2), sympy, networkx, PyWavelets (pywt), xarray, astropy, iminuit, uncertainties, xgboost, lightgbm, h5py, Pillow; and, from PyPI the first time they are imported (an internet connection needed then), lmfit (fits with parameters and bounds, models added together), seaborn, pingouin (statistics in tables: ANOVA, post-hoc, effect sizes), pybaselines, emcee (MCMC), pint (units), tifffile, openpyxl. The menu of examples has a fit with lmfit, a random forest with scikit-learn, blobs with OpenCV and statistics with pingouin. Inputs: connect anything to A, B, C …; a column is a numpy array, a value a float, a dataset a Table (its columns by name, A["Wavelength (nm)"]; A.df a pandas DataFrame; its designations kept), a matrix a 2D array, a workbook a dict of Tables by sheet; each input can be renamed (wl instead of A). Outputs: every variable the code makes is an output, by its kind; a number, a 1D array or list or Series (a column), a 2D array (a matrix), a DataFrame, a Table or a dict of equal columns (a dataset, the column names and designations kept: roles(df, x=…, y=[…])); untick those you do not want as ports. The code runs only when you press Run (Ctrl+Enter): a project opened again runs it once, for its outputs; “Auto run” (off by default) runs it at every change; print and the last expression (a table for a DataFrame) are shown in the node, an error with its line. Stop ends a run that does not end. Options: the inputs (their names in the code, what each is in Python: a column a numpy array, a table a Table with .df a pandas DataFrame, a workbook a dict of Tables, a matrix a 2D array, a value a float, a module; and a line that uses it), the libraries (loaded, with their version, or loaded at the first import; a click puts its import at the top of the code). A script’s code is a module too: its “module” output on an input of another script is that module there, by the input’s name (lib.my_function(x), or from lib import my_function); its own inputs go with it, it may use modules of its own, and its code runs again at every run of the script using it (keep it to functions and constants); an error in it is said with its line.',
  mathcol: 'Computes a column row by row from its inputs by a formula: connect columns (or single values such as a mean) to the ports A, B, C … (a new port appears when the last one is used) and write a formula of the letters, e.g. A*100, (A − B)/C, log10(A), sqrt(A^2 + B^2). Also i (the row, 1 … n), n (the number of rows), pi, and the functions abs, sqrt, exp, log, log10, sin, cos, tan, asin, acos, atan, atan2, sinh, cosh, tanh, deg, rad, min, max, pow, step. Rules for chosen rows (+ Rule for chosen rows): then, in order, the rows chosen; 3, 7, 12; 10-20; 1:2:100 (every 2nd); 50-end; a condition such as A > 5 and B < 2; or all: get a formula of their own, v being the value the formula and the rules above gave (e.g. NaN to empty two spikes, v*2, if(isnan(v), 0, v)); the rows no rule chose: as the formula gave them, empty, or set to a value. Formulas know < > <= >= == !=, and, or, not, if(condition, a, b), round, floor, ceil, mod, isnan, NaN. Give the result a name (with its unit if it has one: “Absorbance (%)”; empty: the formula, or the input’s name when the formula is one letter). Preset: ready formulas (absorbance from transmittance, wavenumber, energy from wavelength, Raman shift, Kubelka–Munk, Tauc, Beer–Lambert, pH, dB, magnitude and phase, normalized …): the formula and name written, the inputs they expect said. Errors: the errors of the inputs; A ± 0.02, B ± 2%, A ± C (another input), A ± sqrt(A): carried to the result (first order: σ² = Σ (∂f/∂x · σx)², the inputs independent), given on the “error” port. Functions of your own: written before the formula, separated by ; f(t) = exp(-t/3); A*f(B) (they may use the inputs and call the ones before). Complex numbers: the formula in complex arithmetic, j the imaginary unit (i is the row): R + 1/(j*A*C), with abs, arg, re, im, conj, exp, ln, sqrt, sin, cos, polar(r, θ); the part given: real, imaginary, magnitude (also in dB), phase (° or rad). Of the rows where a condition is true: mean(A, B > 0), sum, median, sd, count, minif(A, …), maxif(A, …); a value of another row in every row: at(A, 3) (row 3), first(A, between(B, 10, 20) or B == 7), last(A, isin(C, 0)) (several rows matching: the first or the last used, and said; none: empty, and said). isin(x, 2, 5, 7): 1 when x is one of them; between(x, low, high): 1 when x is between them. Random values: rand(), rand(low, high), randn(), randn(mean, sd), randint(low, high), another in every row and the same every time the formula is computed (New random values: others). ƒ Functions: every function by group, with what it does and an example, put in the formula by a click; Value from a row… writes at(…), first(…), mean(…) … from a column and conditions chosen.',
  gencol: 'Makes a column: evenly spaced values (from – to, a number of points), a start and a step, a formula of the row i (1 … n), random values (uniform or normal, with a seed: the same seed gives the same numbers), or values typed (10, 20, 35: separated by commas, by ; with a decimal comma: 1,5; 2,3, or one per line; text too: a column of labels; as many rows as typed). A column on the “like” port sets the number of rows (values typed: those not typed empty, said).',
  columns: 'The columns of a dataset, anywhere in the graph: a row per column; drag ⠿ to move it, untick to leave it out, a new name, its designation (X, Y, ±Y, Label …). Data from an Import or a Workbook with several sheets: Sheet, at the top, chooses the sheet (its workbook output is then connected by itself): or every sheet (a workbook out): then Columns, same for every sheet (the settings made once, the columns matched by their names; Shown: the sheet listed) or own for each sheet (Editing: the sheet whose columns are set here; a sheet not set yet takes the common settings: marked common or own in the list; Copy to all: this sheet’s settings for every sheet). Every column has its letter in the list (A, B, C … by its place, as in a spreadsheet). A column connected to a port A, B … is a column of its own, at the end (place… puts it after, before or instead of another; drag it), also usable in the formulas as {A}. Settings are kept by the column’s name, so a file read again with the same columns keeps them. + Column… adds a column (ƒ in the list), of the kind chosen (changed later in its card): a formula of the columns, row by row; a column written by its letter in the list or as [its name], e.g. B / C * 100 or [R 400 nm] / [R 410 nm] * 100 (a click on a letter under the formula puts it where the cursor is; the first values of the result are shown under it), the functions of Math column, i the row, n the rows, mean([…]) max([…]) … of a whole column, a column added above it; a column of an input (A, B …: its name its own until you write one) or a copy of a column; generated values as in Generate column (evenly spaced, by a step, a formula of the row i, random with a seed), as many rows as the data; or one value in every row; or values typed (Values: 10, 20, 35 — separated by commas, by ; with a decimal comma: 1,5; 2,3, or one per line; text too: a column of labels; the rows not typed empty, said); its place: at the end, after a column, or instead of one (that one left out); a formula may use columns left out. Moving or renaming a column (by hand, or all at once) keeps every formula right (a letter follows its column): a formula is kept by the names the columns come in with and shown with their names now; a column missing upstream is said and its result left empty. The ports A, B, C … (optional): columns or single values from elsewhere; {A} in a formula, copied, or giving the names. Rename columns: How chooses the way shown (the others already set stay on, listed under it with × to take one off; the names before → after under it): new names, replace a text, a text before / after; on the columns they apply to (all, the Y columns, those listed (2-4, B-D, names), or those ticked in the list: a second, orange box on each row), new names given to them in order (one per line, or separated by ; or ,), then replace a text in every name (e.g. take “R · ” out of “R · cavity d = 150 nm”), add a text before / after every name: a name written by hand wins; names from a row of the data (click the row among the first rows shown, or type its number; that row becomes the header and leaves the data; a column that was text only for its header is numbers again); names from a column: its values, in order, become the names of all the other columns, of the Y columns or of those listed (2-4, B-D), that column kept or left out. Outputs: the dataset; the names as a column (text; its values the blocks’ values when the columns come from Split into columns). The columns added fold to one line each (the arrow by their name: the name and the formula), or all at once (Fold all / Unfold all). The formulas of the columns added know every function of Math column (ƒ Functions lists them; Value from a row… takes one value of another row: first([x], [k] == 5) …), and rand() with New random values.',
  stats: 'Descriptive statistics, missing and masked values left out: N, missing, mean, standard deviation, standard error, min, quartiles, median, max, range, sum, coefficient of variation; more if asked: percentiles (10, 50, 90: P10, P50, P90, as D10, D50, D90 of a size distribution) and the confidence interval of the mean (90, 95 or 99 %, from t), each an output. On columns: of a column; every statistic one value (an output, e.g. the mean into a Math column, to normalize): or of the columns of a dataset (2-4, B-D, names, A*; empty: the Y columns): every statistic a column, a value per column, and a table (a row per column, Mean as Y and SD as ±Y). On rows: every row over the columns chosen; e.g. three replicates → mean ± SD at every wavelength; every statistic a column, X on the same rows, and a dataset with X, Mean (Y) and SD or SE (±Y) ready for Plot these columns. Rows used (both): all, ranges by row number or by X value (+ Add a range), a list (3, 7-12, 50-end) or where (conditions chosen, or a formula of x, the columns A, B, C …, i, n). Control chart (on columns): of the first column, its values in order; individuals and moving ranges (I–MR) or the means and ranges of subgroups of 2 to 10 (X̄–R): the centre line and the 3σ limits from the ranges, the points out of control by the Western Electric rules; on the “control chart” output (value, CL, UCL, LCL designated Y for a Plot).',
  blandaltman: 'The agreement of two methods measuring the same things (Bland & Altman 1986, 1999) as a whole figure, with the tabs of a Plot and its figure output to a Merge. Data: two columns (A and B; masked rows left out), optionally a column of groups that colours the points. X: the mean of A and B, A or B (a reference method), or their geometric mean; Y: the difference A − B, the difference in % of the mean, or the ratio A / B (on a log axis, the limits from the logs). Limits: bias ± z·SD (z = 1.96 at 95 %), nonparametric (the median and the 2.5th and 97.5th percentiles), or from a regression on X (Bland & Altman 1999: the bias b₀ + b₁x, the spread from the absolute residuals, limits ± z·√(π/2)·(c₀ + c₁x)). Confidence intervals of the bias (t) and of the limits: approximate, SE = SD·√(1/n + z²/(2(n − 1))), or exact (Carkeet 2015, the noncentral t; up to n ≈ 350 at 95 %): drawn as shaded bands. The regression of the differences on X (proportional bias: slope, p), the line of equality, the values written at the right of the lines, outside the frame (the name over the value, one number of decimals for all). Colours: every group, and every line (bias, upper and lower limit, regression, equality); ⚙ beside a colour: that group’s symbols or that line’s width, dash, shown or not. Outputs: the figure; the statistics of all the pairs and of every group (N, bias, SD, limits, their intervals, the regression on X, the share of the pairs within the limits); the points (group, A, B, X, Y).',
  pie: 'Pie and doughnut charts as a whole figure, with the tabs of a Plot and its figure output to a Merge; no axes are drawn, the pie fills the frame. Kind, chosen at the top of its options: ● Pie (one value column), ◎ Doughnut (a hole, Hole %; a total or a text in the middle) or ⊚ Nested rings (a ring for every value column, the first outside; Rings apart %). Data: categories and their values, or raw values with their groups, counted, summed or averaged. Every slice its share of the total; the start angle (90° = 12 o’clock) and the direction (counterclockwise by default); the slices as in the data, largest or smallest first; the small ones merged into “Other”; a hole (doughnut), the size of the pie, the gap between rings. Labels: percent, value, name, or a name with its percent or value; inside the slice, outside on a leader line (pushed apart so they do not overlap), or automatic (outside when the slice is small or the label long); decimals; small ones hidden. The total or a text in the hole. The edge (white by default) and the opacity; every category its colour, and ⚙ beside it: the slice moved out (exploded), its own opacity, edge and hatching (also in the legend). Output: the figure, and every slice (ring, category, value, percent, its angles).',
  contour: 'Z over X and Y as a whole figure, with the tabs of a Plot and its figure output to a Merge. Data: X, Y, Z columns; on a grid (found by itself, in any row order) or scattered (Z interpolated linearly on the Delaunay triangles of the points to a regular grid), or a Y column and Z columns whose names hold their X (“400 nm”, “410” …). Or a matrix on the matrix port (Matrix, Matrix computation): drawn as its cells; the axes by the column and row numbers or by the X and Y of the matrix (a matrix made from a map keeps them), row 1 at the top (as a matrix is written) or at the bottom (as a map), square cells, the values written in the cells (decimals, size; black or white by the colour under them, or a colour), the names of the rows and columns on the axes. Or the map made from X, Y points: counted in square bins (a 2D histogram) or their density (a Gaussian kernel, Scott’s width × a factor), the points drawn over it if asked; a vector field: U, V columns at every X, Y (a grid, or scattered and interpolated): drawn as arrows (on every N-th point, the longest as long as asked) or as streamlines (how close they run), its speed as the map (or no map). Drawn as a heatmap (every cell its colour, sharp or smooth: bilinear), filled levels (the colour of the band between two levels), contour lines (marching squares: the crossings linear along the cells’ edges), or a heatmap / filled levels with the lines over them; the level written on every line. Levels: nice values (about N), N even ones, every step, or a list; a log Z. Colour maps (viridis … , your 2–3 colours), reversed; the Z range; a colour for the cells without a value; a colour bar (with its title). Profiles: as many as wanted (+ Profile), each Z along a row (at a Y) or a column (at an X): typed, or placed with the mouse on the map (⌖), with its own line on the map (shown or not, colour, dash, width); the row output: X and a Z column per row profile, the column output: Y and a Z column per column profile. Drawn with all the data, or fast: the grid averaged into at most N cells a side (the outputs keep all). The lines: their dash, the levels below 0 dashed (or not), the values on every N-th level, their size and colour. Outputs: the figure, the grid drawn (X, Y, Z), the row and column profiles.',
  smith: 'A Smith chart: impedances, admittances or reflections drawn as Γ in the unit circle (antennas, matching networks, transmission lines, S-parameters). Data as: Z (R and X, Ω) or Y (G and B, S), normalized by Z0 (50 Ω unless typed, or given normalized already), Γ (its real and imaginary parts, or its magnitude and phase in degrees), or S11 (dB and phase); the frequency orders every curve (a curve per value of a column if chosen). Look: a line, symbols or both, one colour or coloured by the frequency on a colour map (with its colour bar), arrows of increasing frequency. Markers at frequencies typed (the nearest point of every curve): its number at the point, and a table in a corner (chosen) saying f, z (or Z in Ω), Γ (magnitude and angle), VSWR, return loss, a line each in the colour of its curve; every point says them under the mouse. Its Axes tab: the grid of impedance (circles of constant r, arcs of constant x), of admittance (their mirror), or both (in its own colour), coarse, medium or fine or your own circles and arcs, its colour, width and labels (r along the real axis, x around the rim, 0 and ∞), the matching circle r = 1 bolder, circles of constant VSWR and arcs of constant Q, a scale outside the rim (the angle of Γ, or wavelengths toward the generator). A point outside the circle (|Γ| > 1) is drawn at the rim and said. Out: the figure (for a Merge, an inset).',
  polar: 'Polar and radar charts (θ–r lines and symbols, polar bars, wind roses, radar / spider charts) as a whole figure, with the tabs of a Plot and its figure output to a Merge; no axes are drawn, the chart fills the frame. Polar: an angle column (degrees or radians) and one r column or more, a curve each: lines (drawn along θ, so equal r is an arc), lines and symbols, symbols, filled to the centre, closed, or bars (a wedge each: a wind rose, as wide as the step between the angles or as chosen); 0° at the right or at the top, counterclockwise or clockwise; a sector of the circle (from – to: 0 – 180 a half circle, for a radiation pattern); the range of r (the centre’s value can be below 0: dB). Radar (spider): categories as spokes, evenly around, a closed polygon per value column (filled), the grid as polygons or circles. Its Axes tab (the 2D axes of a Plot do not apply): r, its limits, a step or about how many circles, reversed (the largest at the centre), a hole in the centre, its values (along a chosen spoke, their format, decimals and text, or none) and a title along that spoke; θ, where 0° is (right, top, left, bottom or any angle), the direction, the sector, the spokes every so many degrees, their labels (degrees, radians as π/2 …, a compass of 8 or 16 points, typed, or none) with their text and distance, minor spokes (and minor circles halfway), ticks outside the rim, a title under the chart; the grid, circles or polygons, its colour and every family its own look (the circles, the spokes, the rim, the minor ones: shown, colour, width, dashes, opacity); the disc filled and bands of colour every other ring. Every series its colour and ⚙ its own line (width, dash, shown), symbols and fill opacity. Output: the figure.',
  scattermatrix: 'Every pair of 2 to 10 columns, row against column, as one figure of k × k panels: X shared down every column, Y along every row, the numbers and titles on the outer panels. Off the diagonal (below and above chosen apart): the points (coloured by a column of groups, a legend of the groups at the right), the correlation written (Pearson r or Spearman ρ, larger when stronger, with stars when p < 0.05), or nothing; least-squares lines over the points. On the diagonal: the histogram (automatic bins) or the kernel density (Scott) of the column, scaled into its row’s range, or its name. The Axes tab styles every panel, the Page tab sizes the whole matrix; the gap between the panels. Every group its colour and ⚙ its own symbols and opacity. Outputs: the figure, and the correlations of every pair (r or ρ, p, N).',
  plot3d: 'A 3D graph as a whole figure, with the tabs of a Plot and its figure output to a Merge: drawn as vectors (SVG, PDF). Draw: a surface, a wireframe or 3D bars of Z on a grid (X, Y, Z columns (on a grid or scattered, interpolated) or a matrix, read as the Contour reads them; or a matrix itself on its input, as an Image analysis gives the heights of an AFM scan; drawn on at most N cells a side, the data averaged), symbols or lines through X, Y, Z points (a curve and a colour per group), or a waterfall: the Y columns of a sweep, each at the depth of its swept value (Split into columns’ blocks, the numbers in the names, or the order), filled down to the floor (walls: every curve, the chosen ones or none; in the line’s colour, one colour for all, or each its own); the depth axis labelled by its values, the curves’ names, or typed (comma-separated, in the curves’ order; an empty one: no label). View: the azimuth and the elevation (sliders, typed, or ready views: default, front, side, top, low), perspective (the eye’s distance), the box’s sides in proportion. Colours: by Z on a colour map (its range, reversed, a colour bar), one colour, or every group / curve its own, or (symbols, lines) by a 4th column on the colour map, its name on the colour bar (⚙: its own line, symbols, opacity). Surfaces: opacity, shading by the light, a mesh every N cells (colour, width), the floor: the map of Z or its contour lines; bars: width, edges; symbols: shape, size, fill, lines down to the floor, fainter when far (depth shading); lines: dash, width. The box: the three back walls and their grid (colours, or none), its edges (the walls’, all, none), about how many values an axis. The Axes tab under the figure (the 2D axes of a Plot do not apply to a box): X, Y and Z each its title (empty: the data’s name), its text and how much farther it is, its limits (empty: the data’s; outside them the scene is cut), reversed or not, its values every step or about how many, their format (decimal, scientific, engineering, SI prefixes, percent) and decimals, shown or not, their text (font, size, colour), the ticks out, in or none and their length. The look of a surface: filled or hidden (only its mesh, contours or projections left), in bands of colour, its underside in another colour, its own light (azimuth, elevation) and shine, contour lines on it; the mesh along X and Y, X or Y only, one colour, by Z or darker than the surface, its opacity and dash; the ceiling (the map of Z), the back walls (the curves of the surface or its filled outline, every N), the projections’ opacity, a curtain down from the edges (one colour, or like the surface: every piece of the edge in the colour of its top, continued down; its opacity a slider). On the figure: Zoom (a rectangle, or the wheel about the mouse), Pan, Out, Rescale (all, or one axis): kept in the node; ⌖ Reader: snap to the nearest data point, or on the surface, with its X, Y, Z and dashed lines to the walls (arrows move it, Esc stops). Marks: lines, arrows, vertical lines, rectangles (level at a height, or upright across X × Z or Y × Z) and points (+ a kind, then click on the figure) Draw on: free (a data point near the mouse, else the surface, else the floor) or a plane (the floor, the X wall, the Y wall, X, Y or Z at a value: e.g. a waterfall curve’s depth): exactly under the mouse, a rectangle lying in it; Snap: the points rounded to the axes’ grid (halves, tenths); the mark follows the mouse from its first point; Draw to draw one again, or type the values; its place: in depth with the data (hidden by what is in front of it), in front of the data or behind them; colour, dash, width, opacity, heads at both ends (arrow, open, bar; their size), a fill, a symbol and its size, a line to the floor, a label, and its projections on the floor and the back walls (dashed, fainter; New marks projected on: the default for new ones). Everything is drawn from the farthest to the nearest.',
  waterfall: 'The curves of a sweep one behind the other as a whole figure, with the tabs of a Plot and its figure output to a Merge. Data: the Y columns, a curve each, with each one’s X (designated) or one X chosen; Z, the value each was measured at (the blocks’ value given by Split into columns, the number in the names, or 1, 2, 3) and its name. Every curve shifted from the one before by a step in X and Y (% of the data’s range, or in its units); the first or the last curve in front (the lowest); every curve as measured or divided by its maximum. Fill down to its baseline: hiding the curves behind (hidden lines, in the page’s colour or one chosen), in the curve’s colour with an opacity (ridgeline), or none. Colours: each its own (recoloured one by one), or by Z on a colour map (reversed, a colour bar with Z’s name); every curve its own look (⚙: line, symbols, fill opacity). Lines (dash, width), symbols, the baselines as thin lines, Z written at every curve: after its end or before its start (out of the frame), or above its end or start (in the frame, as a ridgeline): (“{z} nm”, decimals, size, colour). Outputs: the figure, the curves as drawn (shifted).',
  ternary: 'Three parts of a whole as points of a triangle as a whole figure, with the tabs of a Plot and its figure output to a Merge; no axes are drawn, the triangle fills the frame. Data: three columns, A (the top corner), B (bottom left), C (bottom right): every row divided by its sum, as fractions or percents (rows with a part missing or below 0 left out), and a column of groups: a curve each, in its colour, in the legend. Colour by: a column whose values colour every point on a colour map (reversed if asked), its colour bar at the right. Drawn as symbols, lines and symbols, or lines; the grid every step (0.1 …: lines of equal A, B and C), the values along the edges (A on the left edge, B on the bottom, C on the right, counterclockwise), the columns’ names at the corners. ⚙ beside a group’s colour: its own symbols and line. Output: the figure.',
  probplot: 'A sample against a distribution as a whole figure, with the tabs of a Plot and its figure output to a Merge. The groups: a column each, or raw values with the column of their groups (masked values left out). Kind: ECDF: the empirical cumulative distribution as steps (or points), as a probability, percent or count, or 1 − F (survival), with the distribution’s CDF over it and a band (pointwise F ± z·√(F(1 − F)/n), or the simultaneous one of Dvoretzky–Kiefer–Wolfowitz); Q-Q: the sorted values against the quantiles of the distribution at their plotting positions (standard: location 0, scale 1 with the fitted shape; or the fitted distribution, in the data’s units); P-P: the distribution’s CDF at every value against its position, the line y = x and the DKW band; Probability: the values against their positions on a probability axis on which the distribution is a straight line (Normal, Lognormal and Weibull with the data on a log axis, Exponential, Logistic, Gumbel; Uniform linear; Gamma: its quantiles with the percents written at them). Distributions: Normal, Lognormal, Exponential, Weibull, Gamma, Logistic, Gumbel, Uniform; fitted by maximum likelihood (the location 0 for the positive ones) or given. Plotting positions (i − a)/(n + 1 − 2a): Blom (a = 3/8), Benard (0.3, median ranks), Hazen (0.5), Van der Waerden (0), or Filliben’s. The line: the distribution, least squares, through the quartiles, y = x; a pointwise band around it (the standard error of an order statistic, b·h′(p)·√(p(1 − p)/n)). Exchange the axes with Swap. ⚙ beside a group’s colour: its own symbols, line and band (colour, width, dash, shown or not); what is not set stays as the node’s. Outputs: the figure; the statistics of every group (N, the parameters, the probability plot correlation r, the least-squares slope and intercept, Anderson–Darling A² with its p for Normal / Lognormal (as the Normality node) or the 5 % critical value for Exponential, Logistic, Gumbel, Kolmogorov–Smirnov D); the points (every value, its position, the theoretical and standard quantiles, the CDF, the ECDF). Life data (reliability): a Status column; 1 or F failed, 0 or S suspended (still running when the test stopped, right censored); the failures plotted at Johnson’s adjusted ranks, the fit with the suspensions; Estimation: maximum likelihood, or rank regression X on Y (RRX) or Y on X (RRY), the usual Weibull ways; threshold γ: 3 parameters (Weibull, Lognormal, Exponential, Gamma): the values less γ, by the profile likelihood or the straightest plot; B lives (“1, 10”: by when 1 % and 10 % failed) with their intervals and the intervals of the parameters (Fisher matrix); the ECDF with suspensions is Kaplan–Meier’s (the suspensions marked +, Greenwood’s interval on the log–log scale). On a probability paper: the parameters in a corner (Weibull as β and η), the 63.2 % line (η; else the median), the Fisher bounds of the fit; choosing “probability” turns on the grid, the fitted line and the parameters. Checked against the Python packages reliability and lifelines.',
  boxviolin: 'Boxes and violins as a whole figure, with the tabs of a Plot and its figure output to a Merge. The groups: a column each, or raw values with the column of their groups (and subgroups, side by side; two subgroups can split a violin, a half each). A box: the quartiles (linear interpolation), the median, the whiskers: to the furthest values within k·IQR of the box (Tukey, k = 1.5), percentiles 5 – 95 or 10 – 90, min – max, or mean ± SD, a notch (the median ± 1.57·IQR/√n), the mean (a diamond), the values beyond the whiskers (open circles). A violin: the Gaussian kernel density (Scott, Silverman or a width) from the smallest to the largest value or two widths past them, every violin as wide, one scale for all, or by the number of values; a box, quartile lines or nothing inside. Half violins with their boxes, or a raincloud (a half violin, a narrow box, the values beside). The values themselves over them: spread (jitter) or side by side (swarm). “n = …” under every box (its number of values). Horizontal; colours by subgroup or by group; opacity, edge, median, hatching, rounded corners, gradient (two colours), shadow; a gradient of its own for any group (→ beside its colour: a second colour at the base); significance brackets between the groups (stars or p: tested here, from a post hoc table on the p values port, or written; between the groups or the subgroups within each); ⚙ beside a colour: that subgroup’s (or group’s) own opacity, edge, hatching and median colour. Outputs: the figure, and the statistics of every group (N, mean, SD, min, Q1, median, Q3, max, the whiskers, the notch, the outliers).',
  barchart: 'Columns or bars as a whole figure, with the tabs of a Plot (axes, legend, annotations, page, insets) and its figure output to a Merge. The data: a table: the categories (text: written on their axis at 1, 2, 3 …; numbers: at their values; else the row number) and one or more value columns, each a series, with their ± errors (designated or chosen), or raw values with the column of their groups (and of subgroups: the series): every bar the mean, median, sum or count of its values, with ± SD, SE, the 95 % CI of the mean, min – max or Q1 – Q3, and the values drawn over it if asked. Bars grouped side by side (a gap between them), stacked (positive values up, negative down), 100 % stacked, overlapped, or floating: from the first column to the next ones (min – max, a Gantt); vertical or horizontal; the categories of text sorted by their value (the first series’, or the total when stacked), largest or smallest first; their width, a base line; coloured by series or by category (the categories then in the legend); opacity, edge, hatching, rounded corners, gradient, shadow; a gradient of its own for any series or category (→ beside its colour: a second colour at the base); ⚙ beside a colour: that series’ (or category’s) own opacity, edge, hatching and error-bar colour; error bars (±, or + only; caps); the values written beyond, inside or in the middle of the bars (decimals; small ones hidden). Waterfall (bridge): every value a step from the running total (increases, decreases and the total in colours of their own), a total bar, dashed connectors. Significance: brackets between the bars with stars or p; tested here (Welch or Student t, Mann–Whitney with Holm / Bonferroni, Tukey, Games–Howell, Dunn), read from a post hoc table on the p values port, or written; all pairs, each against the first, neighbours or a list; stacked so they do not cross. Overlay port: datasets whose curves (X: numbers, or the names of the categories; Y, ±Y) are drawn over the bars as lines and symbols: on the same scale or on a second axis at the right (at the top for horizontal bars). Output: the figure, and what is drawn (category, series, value, errors, N).',
  histogram: 'A histogram as a whole figure, with the tabs of a Plot (axes, legend, annotations, page, insets) and its figure output to a Merge. Columns: chosen, else the designated Y (masked values left out); several are overlapped, stacked or side by side. Bins: automatic (the finer of Sturges and Freedman–Diaconis), Sturges, Scott, Freedman–Diaconis, √n, Rice: equal bins over the range of the values (or the range given), a number of bins, a width (from a start), or the edges written; every bin [a, b) but the last [a, b]. Height: the count, percent, probability (adds up to 1) or density (area 1) of the values counted; cumulative. Bins on a log scale (equal in log x, for values spread over decades; the X axis then logarithmic). Weights: a column of weights, every value counted that many times (the bars, the fits to the bars, the mean and the median weighted; the fits from the data take every value once). Marks: a line at the mean (dashed) and the median (dotted) of every column, their values in the legend; a rug: every value a short tick along the bottom. Drawn as bars (a gap between them, an opacity, an edge), as filled steps or as the outline of the steps. Fits: Normal: from the data (mean and SD with n − 1) or fitted to the bars (a Gaussian, least squares); two normals: from the data by maximum likelihood (EM) or two Gaussians fitted to the bars; Lorentzian: the Cauchy distribution by maximum likelihood, or fitted to the bars; a Gaussian kernel density (Scott, Silverman, or a width); several Gaussians or Lorentzians (2 – 6) fitted together to the bars (for peaks that overlap), started at the highest bars or at the positions written, each peak drawn too if asked. Lognormal, Weibull, exponential and gamma: by maximum likelihood (the values above 0), their parameters ± errors from the Fisher information. Fit ranges, as in Fit: ↔ Add a range, then drag across the figure (its edges dragged at any time; All X: none; listed under Fits, ✕ removes one); the fits take only the bars in them, or the values in them: a normal or a Cauchy then by the likelihood of the values cut to the ranges, so the tails beyond them do not make the width too small. A fit per range: every range fitted on its own (two peaks: two ranges, one Normal, a result for each), else all the ranges together; a fit can also take one range only (on, in its row). Its curve is drawn over its ranges (or all the bins), the ranges written in its legend entry and results. Each with its parameters ± errors (FWHM, height, area), χ² of the counts against the counts expected in the bins (dof, p), R² and AIC; ⚙ beside a column’s colour: its own opacity, edge, hatching and the line of each of its fits (colour, width, dash, shown or not); Copy (a table to paste into a spreadsheet) and Save CSV; outputs: the bins, the fit results (a row per parameter), the fitted curves.',
  plot1d: 'A whole figure (Curves: each folds to one line (⊟ / ⊞; Collapse all / Expand all; folded by themselves above 6 curves), or the whole list to one line (▾ N curves), its connections kept: in the node and, apart, in the options panel (its columns, fits and style hidden). + Curves from the columns: the sheet (a workbook), the X (the one designated on the left of each Y, the X of curve 1, or a column) and the Y columns ticked, a curve each; or the curves of the sheet’s designations. Insets: other Plots connected to its insets port drawn inside its frame; their place in % of the frame, dragged with Edit layout or typed in the Insets tab, a background (as the inset Plot’s page (white, or none when it is transparent), none, or a colour), and zoom: the part an inset shows marked here by a rectangle joined to it by two lines, their colour, width and line set; in a Merge an inset goes with its Plot): its curves, axes, legend, annotations and page; the figure drawn on top (as in Origin: a click on a part of it (an axis, its numbers or title, the legend, a curve, an annotation, the frame) outlines it, a double-click opens it in the options panel: the axis on its side, the legend, the curve’s style, the annotation, elsewhere the page; in a Merge, the Plot the part is of; drag the legend and the annotations (an annotation clicked shows its handles: its ends, sides, turn); Edit layout moves and resizes the frame; Large view; grey / colour-blind views; exports SVG, PDF, PNG, TIFF with its dpi, Copy; Zoom, Pan, Zoom out, Rescale change the limits of the axes; ⌖ Reader: the values read off the figure: snap to data; a crosshair on the data point nearest the mouse (on the nearest curve, or on the curve chosen), its curve, X, Y and row, the other curves faded grey; a click keeps it, ← → along the curve, ↑ ↓ to another curve (or free) the coordinates of any place, in every axis of the frame, the arrows move it (Shift: 10 px)). Several Y or X axes, as the double Y and multi-Y of Origin: in the Plot… dialog, Y axes (double Y; one left, the others right; left and right in turn; all on the left) and X axes (bottom and top in turn; all at the bottom); or for each curve, its axes beside its legend text (Y1, Y2 … and X1, X2 …), where “+ new Y right / left” (“+ new X top / bottom”) makes one. A new axis has its own scale, is moved out from the frame and is coloured as its curve (Axes ▸ the axis ▸ Colour: of its curve); an axis no curve is on any more goes away. Values on the axes (Axes ▸ X1 / Y1 ▸ Values): numbers; categories: a column of text (or numbers taken as names) on X or Y, every name at a place 1, 2, 3 … written at its tick, in the order of the data, sorted or as you list them, the points of a scatter spread around their name if asked; dates and times (2024-01-05, 05.01.2024, 5/1/2024 read day / month or month / day, 13:20, durations h:mm:ss): calendar ticks (seconds to years), labels automatic or written with yyyy, MMM, dd, HH, mm, ss; automatic: categories for text, times when every text reads as one. Scales: linear, log (ticks at the powers of 10, 2 or e), symmetric log (through 0: linear within ±a value you choose), reciprocal, probability, logit (0 – 1). Curves stacked (stacked areas, each filled down to the one under it) or as % of their sum; joined at every X (a dumbbell chart); the named style “Curves: lollipop” gives a symbol on a stem. Curves: each has its ports; Y, X (when absent: the X of the first curve if it has as many rows, else the row number), ±Y and ±X errors (bars or a shaded band, only when given), and, when its style asks, a column that colours the points, one that sizes the symbols or sets the line’s width (port size), one with point labels; or the columns of the dataset port chosen by name (+ Curves from the columns, From the designations). + Add curve adds a curve with its ports (then connect a column to Y, a dataset to its data port, or choose its columns); + Curves from the columns adds several from the dataset. Each curve can be hidden (its box: not drawn, not in the legend nor the limits of the axes; still a line to fill to) and has its style (▸ style): line, scatter, line + symbols, steps or a smooth spline; colour, width, dash, opacity; 12 symbols, filled in the curve’s colour, open or in a colour of their own with its opacity (white hides the line behind them), a mark inside them (a dot, –, +, ×, ○, |, /, \\: its size, colour and width); fill under the curve: down to y = 0, to the frame, to a line y = … (a number or a formula of x), to another curve of the Plot (chosen from the list, e.g. a baseline) or to points (placed on the figure with the mouse: click, drag, double-click to remove; or typed); the line’s ends and corners, a halo around it (its colour and opacity: it reads over other curves), arrow heads at the curve’s start and end; drop lines; the fill hatched (lines, dots, staggered dots, rings, squares, small crosses, bricks, zigzag, waves, checkerboard, or a text of your own of at most 5 characters: letters, signs, emoji; ⋯: its spacing, line, size, angle, opacity, background, staggered rows; the same hatching on bars, boxes, annotations and the ranges of a quick fit); colour by the row, x, y or a column through a colour map or by categories; symbol size from the row, x, y or a column (the smallest and largest size, the values they stand for, log, reversed, by area, a size key in the legend); the line’s width from the same; with line + symbols, the line behind or in front of them and a gap before each; labels at the points; its name at the end of the line (right of the frame, in its colour, the names kept apart); a rug: every x value a tick along the bottom, every y value along the left, or both, a short tick or a line from the edge to the point (stopped at its symbol), its width, colour, dashes and opacity; its X and Y axis (X1 … X5, Y1 … Y5). Named styles (right-click): pages, axes, legends, curves (and “Use these settings for new nodes of this kind”: every new Plot, Histogram … starts with this one’s settings, kept in this browser); “Curves: peak fit” gives the curves of a Peak analyzer their look (data dots, the peaks filled in their colours down to the baseline, the envelope black). Rows: the rows drawn (1-1001, 5000-end). One point per X: repeated measurements in long form (several Y at the same X): their mean or median, the spread as ±Y (SD, SE, the 95 % CI of the mean by Student t, min – max, Q1 – Q3), shaded unless the errors are asked as bars. Quick fit (+ Fit, several per curve): a line (or through the origin), a polynomial (degree 2 – 6), exponential, power (fitted to ln y, as spreadsheets do), logarithmic, a moving average; peaks: Gaussian, Lorentzian, pseudo-Voigt, Voigt, 1 – 20 of them over no, a constant, a linear or a quadratic baseline, found by themselves or placed by hand (⌖ Place the peaks: a click on the figure adds one, a drag moves it, a double-click removes it); or a formula of x (every other name a parameter): the least squares of the Fit node, the parameters’ starts, fixed values and limits set in a table. Ranges of x as in Fit: ↔ Draw ranges, then ↔ Add a range on the figure and drag across it (the edges dragged at any time; typed too; none: all X), each range fitted on its own or all of them together, the curve over the ranges or over all X; the ranges drawn as bands (shown or hidden; their fill, opacity, edge, line and hatching: exported with the figure). The fitted curve: drawn as a line, scatter, line + symbols or steps; its colour (the curve’s unless set), width, line (a trend dashed, a fit solid), opacity, its 95 % band; ▸ style beside them: all the style of a curve (symbols, fill under it (to another curve of the Plot too), colour map, labels, halo, arrow heads, its axes); each peak on the baseline (dashed) and the baseline (dotted); its legend entry: the equation (or the name) with R², the name, the name with the parameters (on lines under it), none; a results box in a corner (parameters ± errors, the peaks’ areas, the % Gaussian of a pseudo-Voigt, R²; a legend placed by itself keeps off it). All the results in one table (Quick fit results: Copy, Save CSV) and on the “fits” port. An older project’s trend line opens as its first quick fit. Colours: each its own, every curve its own colour (recoloured at once from the menu beside it: a palette: Okabe–Ito, Category 10, ColorBrewer, Paul Tol, greys; from a colour map spread evenly over the curves: viridis, plasma, inferno, magma, cividis, turbo, coolwarm, RdBu, gray; or from my colours: 2 or 3, those between mixed; shown before it is applied, Reversed or not; the menu stays after Recolour, to try another), or by group: the curves grouped and one colour given to each group, kept up to date. Grouped as: auto (the value of the block each came from when they all come from one Split into columns, else their order), their order (each curve a group), the block’s value, the number in the name of its Y column, or a column of the table (or the column on the “groups” port): every curve then split into a curve per value of it (d = 50, 100 …: its equal values, as Split into columns finds them), named by it. The colours: a colour map or my colours spread over the range of the values, or a palette in steps (its colours in turn, in the order of the values); Reversed. The scale shaped, in both ways: the bar shows it as the curves get it; my colours have a handle each on it (drag: where that colour is, more or less room for it); the thin bar under it is the whole map, its ends dragged to use only a part of it (e.g. without the palest yellow of viridis); Balance gives more room to the colours of the start or of the end (double-click: even); Even puts it back. The groups are listed with their colours: click one to give that group its own colour (× back to the scale); a curve keeps its own colour with Style ▸ Colour ▸ own (e.g. a fit in black over its data). The legend can show them as one entry with the colour scale, a colour bar their range. (Points coloured by, in a curve’s style, colours the points of that one curve from a value.) The dataset port takes several datasets (e.g. the data and the fit curves). Tabs: Axes: every side (scale: limits, linear / log / 1/x, ticks by increment, count or values, minor ticks, breaks; line, ticks, tick labels: turned by any angle (45°, 90° for long names; the margin grows to fit) or wrapped after N characters, title: turned by any angle (e.g. a Y title written level), its gap and its place along the axis: start, middle, end or custom, also dragged on the figure), Cross at; the axis drawn where the other is at a value (0 and 0: axes through the origin), its title at the frame’s edge, the top / right axes as a mirror, an own scale or a function of the opposite one (eV over nm), extra axes, grid, frame fill; Legend: shown or not, place, (automatic: inside the frame where it covers the least of the data, found again when they change; too large: under the plot; or outside at the right, under or above the plot, room kept for it; dragged: where it is dropped) entries (order, shown, own text), arrangement, title, frame (none, or a box: its line, rounded corners, fill (a colour or a linear or radial gradient from it) and a shadow, sharp or soft, only outside the box (as under a box filled white, the box itself left see-through); an older project’s line, shadow or rounded frame opens as such a box; the sample’s length and height, the gap between the sample and its text, the padding and line spacing; its text in any font, the box as wide as the text in that font); Annotate: the colour bar a node places by itself (Colour bar ticked: a Contour, a 3D plot, a waterfall) made editable by Edit the colour bar, by a double-click on it or by dragging it (its place, size, values, title; taken out of the list: placed by itself again); the others added by family, each keeping what it is (only close variants change: line ↔ arrow, rectangle ↔ ellipse, star ↔ regular polygon): texts (turned with the round handle above them), callouts (a text in a box with a line to a point), colour bars (vertical or horizontal; their ticks, values and title on either side: right / left, under / over; values auto, every so much, the levels of a filled map, min and max, a list of your own, or none; their format and decimals; ticks out, in, across or none, their length, minor ticks; a map filled by levels shown as its bands); lines and arrows (straight or bent: drag the handle in the middle; + Bend: a point the line goes through; several make a smooth curve through them all, each dragged by its handle; or an elbow: across then down, down then across, across–down–across, down–across–down, its corners rounded, its middle piece dragged; a body of one line, two, tapered, a wave or a zigzag, or chemical: an equilibrium ⇌, favouring a side, a retrosynthetic ⇒; crossed out ✕ (no reaction); a text above and one below it, e.g. reagents and conditions; heads triangle, stealth, open, bar, circle, diamond, square, half), vertical and horizontal lines; rectangles, ellipses, polygons and polylines (their points placed with the mouse on the figure or written; straight or smooth), stars (points, inner size), regular polygons, arcs, pie and donut slices (from – to or an opening, a donut’s hole in % of its size, rounded corners); bands in x or y; brackets and braces (over or under a range of x, beside a range of y, or free in any direction; square, curly or a bar with ends; each leg its own length; turned by any angle (its round handle on its text side), the text along it (turned with it), level or at an angle), scale bars (a length in the units of the data); the closed ones filled with a colour or a gradient (linear from a start to an end, radial from a centre out to two radii: typed in % of the shape’s box or dragged by its orange handles; beyond its ends kept, mirrored or repeated; the second colour’s opacity), hatched, turned; a shadow under any of them (moved, blurred, its colour and opacity), a blur; line ends and corners (how far a sharp corner reaches), dashes of your own (pt: dash gap …); in data units or % of the frame, each on its layer; Page: size (85 mm = one journal column), the default text, background (white, none, or a colour: and a linear or radial gradient from it to a second colour, placed by dragging on its pad), border, a title over the figure (its own font; the frame placed under it), the numbers written with a decimal comma (2,5), the frame placed by automatic margins or by hand. Outputs: the data of each curve (a dataset: X, Y, ±Y, ±X designated, for analysis nodes) and the figure (to a Merge). Each curve can also take a dataset on its own “data” port: its X, Y, ±Y, ±X chosen beside the ports from the columns of that dataset (else its first designated curve). A workbook on the dataset port (Import or Workbook ▸ workbook): every curve chooses its sheet (Sheet, above its columns; none: the first), so one Plot draws columns of several sheets (each named with its sheet). The other graphs (Bar chart, Histogram, Box & violin, Pie, Polar, Waterfall, Contour, Ternary, 3D …) take a workbook too: Sheet, at the top of their options.',
  matrix: 'A matrix: m × n numbers, on the matrix port; for Matrix computation, and drawn by Contour / heatmap. Typed: the cells of a grid (Tab / Enter move, Ctrl+V pastes a block from a spreadsheet or a text file; + / − add or remove a row or a column). Generated: identity, zeros, ones, a constant, diagonal (the values written), random (uniform or normal, with a seed), a formula of i, j (the row and the column, from 1) and m, n (the rows and columns): e.g. 1/(i + j − 1), sin(i)*j, Hilbert, Vandermonde (decreasing powers of the values written) or a 2D rotation by an angle. From a dataset: its columns chosen (empty: every column with numbers but the rows’ Y and the labels), the rows chosen (all, ranges, a list or where); the Y of every row from the column designated X (or one chosen, or none: the row numbers), the X of every column from the number in its name (“R 400 nm” → 400, as the Contour reads a matrix): a map R(λ, θ) cut by Split into columns becomes a matrix with its axes. For any matrix (typed, generated or from a dataset) the rows’ Y and the columns’ X can be custom: a list (400, 410, 420 …: numbers are their coordinates, other texts their names) or a range (from, to: spread evenly; or from, step), with the name of what they are (“Wavelength (nm)”), the axis title on the plots; fewer values than rows or columns: the rest empty (said). Outputs: the matrix, and the matrix as a dataset (the rows’ Y designated X, then a column a matrix column, named by its X).',
  matcomp: 'Operations on matrices: connect matrices (Matrix), columns (a vector n × 1) or single values to A, B, C … (a new port appears when the last one is used), then one step or several: every step an operation on the inputs or on the results of the steps above it (R1, R2 …; a piece of a decomposition: R2 · L), its result under it and on its own port (a matrix, or a value). Element by element: A + B, A − B, A ∘ B, A ⊘ B, A ^ B (B a matrix of the same size, a row, a column or a number: a row or a column is repeated to the size of A), f(A) (abs, −A, 1/A, exp, ln, log10, √, A², round), a formula of a and b (the elements of A and B), i, j, m, n. Products: A × B (matrix product), Aⁿ (n whole; negative: of the inverse), A ⊗ B (Kronecker), A · B and A × B of vectors. Structure: Aᵀ, A⁻¹ (LU with partial pivoting; a warning when nearly singular), A⁺ (pseudo-inverse, by the SVD). Numbers: the determinant, the trace, the rank (the singular values above a tolerance), a norm (Frobenius, 1, ∞, 2, the largest |a|), the condition number (2-norm). Systems: solve A·x = B (LU; A not square: the least-squares solution of smallest norm). Decompositions: LU (A = P·L·U, partial pivoting), QR (Householder, reduced), Cholesky (A = L·Lᵀ, symmetric positive definite), eigenvalues and eigenvectors (symmetric: Jacobi rotations, the values ascending; any other: the QR algorithm, complex values as Re, Im; their vectors left empty), SVD (A = U·Σ·Vᵀ, σ descending; V, not Vᵀ). Rearranging: a part (rows, columns: 1-3, 5, 2-end), flip ↔ / ↕, rotate by 90° (counterclockwise), reshape r × c (row by row), [A B] and [A; B], the diagonal (of a matrix: a column; of a vector: the diagonal matrix). Rows / columns: the sum, mean, min, max or product of every column, of every row, or of all (empty cells left out).',
  canvas: 'Several Plots on one page: connect their “figure” outputs; they fill a grid of rows × columns in the order of connection (or as chosen in the Grid tab: the panel of each, or ← → ↑ ↓ to change places with the figure left, right, above or below it in the grid; Facets: a Plot of several curves split into a panel for each), a Plot spanning several cells (cols, rows). Size of the Plots: fit to the cells (the page size chosen here, every Plot redrawn at the size of its cell: fonts and lines keep their pt, the margins found again) or keep their own sizes (the page as large as the grid). Gaps and margin in the page’s unit; shared X / Y axes (all panels, by column / row: one range; the numbers and titles of shared axes on the outer panels only); Column widths and row heights of the grid in proportion (2:1); for all the panels at once: one X title under them and one Y title at their left (their own hidden; the text: yours, else that of the first panel), one legend outside them (at the right, below or above; every curve once; the legends of the panels hidden unless kept), one colour scale for the curves coloured by a map; facets: a Plot split into panels, one per curve, in its place in the grid (Plots list ▸ facets); a ground behind the panel labels. Arrangement: a grid, or stacked; one under another with one X axis, or side by side with one Y axis: the frames touching (or a gap between them), their heights / widths in proportion (2:1:1), the margins around the stack those the Plots need, the numbers and the title of the shared axis on the outer panel only, the ticks at the joints turned inward, and a number at a joint that would run into the next panel left out; panel labels (a), (b) … at the corner of each Plot; Edit layout moves and resizes a Plot (it leaves the grid: an inset, drawn over the others on its page’s background; white, or none when its Page background is transparent; the other Plots stay where they are, placed by hand too; Back to the grid, All back to the grid). Annotate: texts and arrows on the page (% of the page). Exports as a Plot. Output: the figure, the whole page: to a Figure Drawing (to draw on it, or as a guide to draw by: it follows every change), to another Merge as a panel, to Select figures.',
  selectfig: 'Some of several figures: connect a Batch’s “figures” (a Plot from every file or column) or Plots (their “figure”, one or several). Take: all of them, one (chosen from the list: its number and name), or some (ticked, or by a list: their names or numbers, 2-5, 8, R*, !3). One gives a figure, as a Plot’s: annotate it (Figure Drawing), put it in a Plot as an inset, export it alone; several, the figures together: a Merge lays them out, a panel each.',
  drawing: 'A vector drawing on its own page (a scheme, a set-up, a mechanism), in mm: or over a figure: connect a Plot’s (or a Merge’s) “figure” output to its “figure” port (or right-click the Plot ▸ Annotate (Figure Drawing)) and the drawing annotates it, on its page, with every tool of the editor (the figure seen under the page while you draw; in a Merge or as an inset the two go together); “only a guide”: the figure is shown under the page while drawing but the drawing goes out alone, at its size. Each object in front of the figure’s data or behind it (Layer: under its curves, over its frame’s ground and grid); in a Merge or an inset the annotated figure keeps its proportions. A click on an object of the node’s figure (without opening the editor) shows its settings at the top of the node’s options (quick edits: its look, layer, a copy, removal; the pencil opens it in the editor). Objects are placed in mm on the page; one “Pinned to the data” (its options) moves with the Plot’s data when its limits change: the point it holds (an arrow’s head, a text’s place, a shape’s middle) stays on its data point, its size stays in mm. drawn in its editor (✎ Edit drawing, or a double-click on the figure), exported as a Plot is (SVG, PDF, PNG, TIFF, Copy), its figure output into a Merge (a panel of its own, its panel label too) or into a Plot’s insets: scaled there as a whole, lines and texts with it (made at its final size, in a Merge that keeps the sizes it stays 1:1). The editor, over the whole window: on the left the tools, in groups (each shows its last tool used; held, right-clicked or its small corner: the others, with their keys); on top the selection bar (the place and size of what is selected, typed; align, spread out, flip), Snap (to the grid and its step, to objects, to nodes, guides) and View (the grid, the isometric grid, the quick bar, the isometric mode), the zoom; on the right the options of what is selected by tab (Style, Arrange, Path, Make; the page when nothing is) and under them Layers, Components and Library (the border between them dragged: their heights); at the bottom what the tool does, where the mouse is (mm) and how many objects. The tools: select, corners (K: click a shape, then its corners; Shift: more: and drag one inward to round them; their radius also typed: all, or the picked ones; a rectangle’s, a polygon’s, a star’s, a path’s), pen (click: a corner, drag: a smooth node with its curve; click the first node to close the path, double-click or Enter to end it open), image (a picture from a file (PNG, JPEG, TIFF, SVG), also pasted with Ctrl+V or dropped on the page), text, line, arrow, double-headed arrow, curved arrow, elbow arrow (a connector), equilibrium arrow ⇌, retrosynthetic arrow ⇒, dimension (the length written on it, in mm), rectangle, ellipse, polygon, polyline (click the points, double-click or Enter to end), star or regular polygon (one tool: Variant in its options), arc, pie / donut (one tool: Kind in its options; Pie or Donut, the hole, rounded corners), bracket, curly brace (both turned by any angle), callout; drag on the page from one point to the other (Shift: a square, or a line by 15°; a click: a usual size), align (left, middles, right, top, middles, bottom: to the box of the objects selected, or to the page; one object always to the page), spread out across or down (equal gaps), the grid (shown, its step in mm or pt, objects snapped to it), snapping to the edges and middles of the other objects and of the page (a guide shows it; Alt while dragging: free), the zoom (Ctrl + wheel). The options of what is selected in sections that fold: Object (its place, size, points, turn, corners: a rectangle’s one radius or, unlinked, one for each corner), Text, Stroke, Arrow heads, Fill (its colour; a gradient: linear from a start to an end, radial from a centre out to two radii, in % of the shape’s box, dragged by its orange handles on the page as in Affinity, Shift: steps of 15° or a circle; beyond its ends the end colour, mirrored or repeated; the second colour’s opacity; hatching and the hatching’s look), Effects (shadow (its direction, distance, blur, intensity and colour), blur; a text: a shadow of its letters, of its box), then what can be done with it; a text’s lines left, centred, right or justified. The layers, the front object first: shown or hidden (not drawn nor exported), locked (not moved with the mouse; selected in the list), renamed (double-click), reordered (drag one onto another, or front / forward / back / to the back), duplicated, removed; the options of what is selected: all the settings of an annotation (line: colour, width, dash or dashes of your own in pt, opacity, ends, corners and how far a sharp corner reaches; fill, gradient, hatching; arrow heads at each end, their size; bends: a line through several points; shadow: moved, blurred, its colour and opacity; blur), several selected: their line and fill at once; nothing selected: the page (size, text, background (a colour or a gradient), border) and the grid. Paths: any shape turned into a path (Convert to path): its nodes dragged, each with the controls of its curves (a smooth node keeps them in line), a node removed by a double-click, made smooth or a corner by Alt + click, added by a double-click on the path; its SVG path text edited or pasted; holes by even-odd; all nodes smooth or sharp, closed or open, reversed; closed shapes combined (union, subtract, intersect, exclude, divide: their curves kept), a copy moved out or in (offset, mm), a line made the filled outline it covers (stroke to path), corners rounded (fillet) or cut (chamfer) by so many mm: every one, or only the nodes picked (a click on a node; Shift + click: more); + Node (after each node picked, else in the longest piece), − Node, Break at node (a closed path opened there, an open one cut in two), Join (two open paths or lines made one: their nearest ends one node, or a piece between them). Copies along a path: select the objects and, in front of them, the path (an open one: from end to end; a closed one: evenly round it), turned with it or not. Transform (the selection, about its middle): flip across or down, turn by an exact angle, scale (% across and down, linked or not), skew (degrees), or put it on a face of an isometric box (top, left, right); a rectangle, an ellipse, a star or a polygon stays one when it can, a picture is mirrored, the rest made paths. Select the same: every object of the same kind, fill, line or look. Simplify a path: fewer nodes, none more than so many mm off its outline, smooth or straight (for a line drawn by hand or a figure imported). Arrow heads along a line (Along it: how many, turned back or not), on lines, arrows, polylines and paths. Blend: so many shapes between two, their outlines, lines and fills in steps. Bend along it: the objects selected drawn on the front path, stretched to its length or as long as they are. Pencil (F): drawn freely, made smooth when you let go, closed back on its start. Shape builder (X): two or more closed shapes selected, then a click joins the parts they make, Alt + click takes one away; Apply (Enter). Isometric: an iso grid (View ▸ Isometric grid, points snapped to it); the isometric mode (View ▸ Isometric mode): a cube at the top right, a click on its Top, Left or Right face and the next rectangles, ellipses, stars, arcs, lines, polygons, paths, texts and pictures are drawn on that face (Flat: on the page; ×: the mode off, the objects on faces stay on them); Shift + click a face: the objects selected put on it. An object on a face keeps its own shape (a rectangle stays one, its width and height on the face): its handles move along the face’s edges, the arrows move it along them; Arrange ▸ Isometric face puts it on another face or takes it off (Flat), where it is stays; a text on a face slanted with it, or upright (View ▸ Texts upright, Arrange ▸ Text upright); Path and Make take it off its face as it is drawn. Snap ▸ Guides along the face: the rulers give guides along the face’s two edges. With nothing selected, a box (width, depth, height, its faces shaded) or a stack of layers (thicknesses, the bottom one first: a device’s films). Guides: dragged out of a ruler, moved (caught a few px either side), back onto it to remove; objects snap to them. The quick bar: dragged by its handle anywhere, it stays there (its pin, or a double-click on the handle: back by the objects). Snap to nodes: points snap to the ends, corners and middles of the other objects and to where their outlines cross; Shift while drawing a polygon or a path: by 15°. Right-click in the editor: on an object; copy, cut, paste, duplicate, its order, group, lock, hide, convert to path, its layer, pin, delete; on the empty page: add any object, paste, select all. A text written along another object’s outline (Along: from so far along it, % of its length; so many pt away from it; on its other side: inside a circle instead of outside). Clip: the objects selected cut to the outline of the front one; Mask: seen through its lightness (a gradient: a fade); Release. Groups (Ctrl+G, Ctrl+Shift+G): selected together (Alt + click or a double-click: one of them). Components: objects kept once (Make component: an instance in their place), placed again from the Components tab, all instances changing with it (Update from objects selected; Detach: objects of their own). Arrays: copies in a grid (rows × columns, mm apart) or round a circle (turned with it or not). Styles: copy and paste the look of an object (Ctrl+Shift+C / V), styles saved by name in this browser; the colours of the selection, each changed everywhere in it. Library (in this browser): objects added from a drawing, SVG files imported as editable paths (their fills, lines and texts), placed in any drawing; written to a file and read back to share it; an SVG file placed straight into the drawing. Connectors: a line or arrow drawn from a shape (or a text) to another stays stuck to them: its ends on their outlines, facing each other (or the middle of a side, or the centre; some pt away), following them when they move; drop an end’s handle on a shape to stick it, elsewhere to free it; an elbow leaves and meets them by the sides its route goes along. On the page: a click selects (Shift / Ctrl: more), a box dragged around objects selects them; drag to move (all those selected), the handles change points (ends, bends) and turn (the round one); a box (rectangle, ellipse, polygon, star, arc, picture) has 8, on its corners and the middles of its sides, turned with it: a side moves alone, a corner two sides (Shift: proportions kept, Ctrl: about the centre); a thin line is found a few px away. Keys: Delete, arrows (a grid step; Shift: ×10; Alt: 0.1 mm), Ctrl+A, Ctrl+D (a copy), Ctrl+C / Ctrl+X / Ctrl+V (also into another drawing), Esc (ends a tool, clears the selection, closes), Ctrl+Z undoes; V, T, L, A, R, E, P choose a tool.',
  note: 'A note on the canvas: what was measured, how, why. A plain note is typed in the node; click it for the whole note in the options panel: a small word processor: paragraph styles (Normal, Heading 1–3, Quote), font, size (pt), bold, italic, underline, strikethrough, superscript, subscript, text colour and highlight; alignment, bulleted and numbered lists, indent, line spacing, the space before and after a paragraph; links; undo. Blocks: a live figure of the project (Figure… (a Plot, a Merge, any graph, a Figure Drawing) drawn from its node now, so it follows the data; or Copy under a figure, then Ctrl+V in the note), pictures (a file, pasted or dropped; large ones made smaller), tables (rows, columns, a header row, merged cells), text boxes (border, fill); a figure or a picture has its caption, numbered Figure 1, 2 … Figures, pictures, boxes and tables: drag the grip (⋮⋮, top left) to move one anywhere in the note, the corner (bottom right) to change its width; its place (left, centre, right) and “wrap” for the text beside it (with the figure selected, or in the toolbar for a box or a table). Formulas (Σ, or a click on one): LaTeX, drawn as it is typed, in the line or on its own line, with a palette of structures, Greek letters, operators and units, and the font of all the formulas of the note (automatic, sans serif, serif, or the LaTeX look). Export: DOC (.docx for Word, LibreOffice, Google Docs: styles, lists, tables, the figures drawn at 300 dpi and numbered, those beside the text floating, the formulas as equations), PDF (print, or the browser’s Save as PDF: vector), HTML, MD (Markdown; with figures or pictures a .zip of the text and their files). Page: as the theme, light or dark; the page on screen (in a dark one the text light, its colours lightened, the figures as they are on white); kept in this browser, the exports always on white. ⤢ (or a double-click on the note) writes on an A4 page of its own; Esc closes it. Formatted, the note is still typed in the node (its figures and pictures there as one line, its tables small); the toolbar, the blocks and the export are in the panel. The grip at its corner sizes the node.',
  frame: 'A named, coloured frame around nodes (they move with it).',
  subgraph: 'A group of nodes in one node: select nodes, right-click → Make a group node. Its ports are the connections that crossed the selection. Open it (button, or right-click) to see and change the nodes inside; ← back returns. Ungroup puts the nodes back. Save as template keeps it in this browser: it appears in the Nodes panel under My templates, to use in any project. A Batch is a group that runs the same analysis on every file. Take one from the Nodes panel (Data ▸ Batch (every file)) or, with the analysis already built, select its nodes (not the Import) and right-click → Make a batch. While it is not ready, the node shows its three steps, each ticked when done: ① Files: connect the workbook output of an Import (several files opened together, or Open a folder) to “files”; ② Steps: open it and build the analysis on one file (it starts from “one file”); ③ Keep: connect to “+ keep” on the Group output what to keep from each file (a value, a table, a Plot’s figure). Inside, the bar at the top chooses the file the steps are shown on (◀ ▶ or the list; ⚠ a file with errors, ✎ one with its own settings) and says what is kept. Every step chooses, at the top of its options (In the batch), whether its changes are the same for all files (the common settings) or each file its own: then a change of it (a fit range dragged, a cut of Split into columns, a window …) is the own of the file shown, the step marked ✎ while that file is shown, the other files keeping the common settings (back to Same for all files: the files’ own settings of that step dropped). Skip for this file: the step does not run on the file shown (faint, ⊘): what reaches it goes on unchanged when it gives the same kind of data (a table to a table), else it gives nothing for that file. The bar lists the steps with the file’s own settings, each ↺ back to the common ones or ⇪ used for all files (they become the common ones), and the steps skipped for it (↺ run again). A change made for all files of a setting the file had its own drops its own of it. The same over columns: each column its own, a step skipped for a column. The steps themselves (the nodes, their connections) are the same for every file; the table gets an Own settings column (also the steps skipped) when some file has them. Out: a table with a row per file (its name, what the name says, the values kept), a workbook with a sheet per file, and every file\'s rows one under the other. A Plot kept: “figures”, every file’s (or column’s) figure, named after it (its texts can hold {file} or {column} and what Names reads, {T} …: filled for every one; the Names buttons at the top of the Plot’s options write them where the cursor is; an index such as C_{OX} is left alone; Select figures takes all, one or some of them): connected to a Merge, a panel each (Panel, ← → ↑ ↓, shared axes as for Plots connected one by one). Besides, every result kept has an output of its own, named as it: a value (or a table of one row, the parameters of a Fit) gives a table with a row per file; a longer table, the rows of every file one under the other. In its options: Over: every file (every sheet of a workbook), or every column of one table: then Sheet (of a workbook), Columns (2-6, B-F, names, R*, !C; empty: every Y column; a ±Y designated right after a column goes with it) and X (one column for all: the designated X unless chosen; the X on the left of each column for a table of X, Y, X, Y … pairs, or the row number); every column is a run of its own (inside: X and the column as Y, named as it), a row per column in the table (e.g. a peak fitted in each of 20 spectra, its centre and width per thickness), own settings per column, Names reading values from the column names (R · d = {d} nm). Names reads values from the file names ({T} for a number, {name:text} for a word, as in sample_{T}C); what it reads from the first name is shown under it; Guess proposes one (the numbers that change from file to file become {V1}, {V2} …: then name them); Order sorts the files; Long tables: the tables of more than one row kept (a curve, a spectrum), every file’s rows one under the other (as said above) or its columns side by side, named after the file (one X for all when every file has the same X, else every file’s X before its columns), ready for a Plot; Kept: every result kept named by hand (empty: the name made from what it is connected to), on its port and in the tables; the files listed with what their names say and their errors: a click shows one inside. A group (not a Batch) names its outputs in its options the same way.',
  groupin: 'Inside a group: what reaches the group’s input ports.',
  groupout: 'Inside a group: what leaves by the group’s output ports.',
  reroute: 'A point on a connection, to route it more clearly (double-click a connection to add one). It passes on whatever reaches it.',
};

